window.STUDY_DATA_TEXT = (window.STUDY_DATA_TEXT || "") + " a; a = a->next; }\\n            else { tail->next = b; b = b->next; }\\n            tail = tail->next;\\n        }\\n        tail->next = a ? a : b;\\n        while (tail->next) tail = tail->next;\\n        return tail;\\n    }\\npublic:\\n    ListNode* sortList(ListNode* head) {\\n        std::size_t count = 0;\\n        for (ListNode* p = head; p; p = p->next) ++count;\\n        if (count \u003c 2) return head;\\n        for (std::size_t width = 1; width \u003c count;\\n             width = width > count / 2 ? count : width * 2) {\\n            ListNode dummy(0, head);\\n            ListNode* tail = &dummy;\\n            ListNode* current = head;\\n            while (current) {\\n                ListNode* left = current;\\n                ListNode* right = split(left, width);\\n                current = split(right, width);\\n                tail = appendMerge(left, right, tail);\\n            }\\n            head = dummy.next;\\n        }\\n        return head;\\n    }\\n};\\n} // namespace hot100::p0148\\n```\\n\\n[查看可编译源文件](../../../algorithms/cpp/solutions/p0148_sort_list.hpp) · [查看完整测试](../../../algorithms/cpp/tests/test_p0148.cpp)\\n\\n## 实现复用与边界检查\\n\\n递归逐节点合并的最坏调用栈为 O(n)，无法满足常数辅助空间目标。此实现自底向上拆段并迭代合并，避免递归栈。\\n\\n## 9. 本地验证\\n\\n400组随机含重复值链，std::stable_sort地址序列作参照；另有3000节点逆序链检测多轮合并。 测试采用固定种子，可复现每轮输入。断言针对返回值，也针对应保持的地址、连接或输入状态。内存由arena或对应destroy工具明确回收。本地测试通过仅说明这些可复现用例通过，不等于完整在线评测结论。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\nc++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0148.cpp -o /tmp/hot100-cpp/test_p0148\\n/tmp/hot100-cpp/test_p0148\\n# 编译器支持时，再检查地址、未定义行为与泄漏\\nc++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0148.cpp -o /tmp/hot100-cpp/test_p0148_san\\nASAN_OPTIONS=detect_leaks=1 /tmp/hot100-cpp/test_p0148_san\\n# 若执行环境在ptrace下明确拒绝LeakSanitizer，可仅运行地址/UB检查：\\n# ASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0148_san\\n```\\n\\n## 10. 面试延伸\\n\\n- 如果只要求O(nlogn)时间、不要求常数空间，自顶向下版为什么更易读？中点拆分直接对应递归定义。\\n- 如何验证稳定排序？相同val节点的最终地址顺序应与原顺序一致。\\n- 链表快速排序为何不一定是好选择？分区接线复杂，坏轴选择仍会退化。\\n\\n## 11. 两道练习与提示\\n\\n1. 给每个节点附加原始序号，仅按val排序，检查相同val的序号顺序。提示：本地用地址→序号映射即可。\\n2. 让split返回{段头,剩余头}并重写主循环。提示：必须仍能找到当前段尾来断开，返回值设计应服务接线不变量。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0152-maximum-product-subarray.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0152-maximum-product-subarray.md\",\"title\":\"152. 乘积最大子数组：C++17 推导与实现\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"动态规划\",\"difficulty\":\"MEDIUM\",\"problemId\":152,\"supplemental\":false,\"questionIds\":[\"LC152\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"非空数组中求连续非空子数组的最大乘积。负数和零均可能出现；不能选择空子数组来把负答案改成0。官方数据保证子数组乘积处于32位整数范围。 题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\",\"minutes\":6,\"headings\":[{\"id\":\"152-乘积最大子数组c17-推导与实现\",\"text\":\"152. 乘积最大子数组：C++17 推导与实现\",\"level\":1},{\"id\":\"题意与调用约定\",\"text\":\"题意与调用约定\",\"level\":2},{\"id\":\"从直觉到优化\",\"text\":\"从直觉到优化\",\"level\":2},{\"id\":\"不变量与正确性\",\"text\":\"不变量与正确性\",\"level\":2},{\"id\":\"算法步骤\",\"text\":\"算法步骤\",\"level\":2},{\"id\":\"手工追踪\",\"text\":\"手工追踪\",\"level\":2},{\"id\":\"完整-c17-实现\",\"text\":\"完整 C++17 实现\",\"level\":2},{\"id\":\"复杂度核算\",\"text\":\"复杂度核算\",\"level\":2},{\"id\":\"c-常见陷阱\",\"text\":\"C++ 常见陷阱\",\"level\":2},{\"id\":\"测试与运行\",\"text\":\"测试与运行\",\"level\":2},{\"id\":\"面试追问\",\"text\":\"面试追问\",\"level\":2},{\"id\":\"练习与提示\",\"text\":\"练习与提示\",\"level\":2}],\"sections\":[{\"id\":\"152-乘积最大子数组c17-推导与实现\",\"heading\":\"152. 乘积最大子数组：C++17 推导与实现\",\"text\":\"> 分类：动态规划 · 难度：MEDIUM · 官方 Hot 100 顺序：88/100\\n\"},{\"id\":\"题意与调用约定\",\"heading\":\"题意与调用约定\",\"text\":\"非空数组中求连续非空子数组的最大乘积。负数和零均可能出现；不能选择空子数组来把负答案改成0。官方数据保证子数组乘积处于32位整数范围。\\n题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\"},{\"id\":\"从直觉到优化\",\"heading\":\"从直觉到优化\",\"text\":\"枚举全部区间要 O(n²)。最大和子数组只需一个最好结尾状态，但乘积不同：乘上负数会把最小值变成最大值。因此同时保存“以当前位置结尾”的最大乘积和最小乘积，下一项只需看当前值、旧最大乘当前、旧最小乘当前三者。\\n\"},{\"id\":\"不变量与正确性\",\"heading\":\"不变量与正确性\",\"text\":\"每个以i结尾的非空区间，要么只含nums[i]，要么是以i-1结尾区间追加当前项。正数乘法保持大小次序，负数逆转次序，零全部归零，所以旧最大与旧最小足以表示所有扩展极值。best再对所有结尾最大值取最大。\\n\"},{\"id\":\"算法步骤\",\"heading\":\"算法步骤\",\"text\":\"1. 用首项初始化最高、最低和全局最佳，保留非空条件。\\n2. 先计算旧highestvalue、旧lowestvalue。\\n3. 分别从三候选中取最大与最小。\\n4. 更新全局best，继续扫描。\\n\"},{\"id\":\"手工追踪\",\"heading\":\"手工追踪\",\"text\":\"[-2,3,-4]：初始最高最低都-2；乘3后最高3、最低-6；乘-4后候选-4、-12、24，最高24、最低-12，全局24。负数把上一轮最差的-6翻成最好24。零会自然切断之前乘积链。\\n\"},{\"id\":\"完整-c17-实现\",\"heading\":\"完整 C++17 实现\",\"text\":\"以下内容来自本课 可编译头文件，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0152 {\\nclass Solution {\\npublic:\\n    int maxProduct(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"maxProduct requires data\\\");\\n        long long highest = nums[0], lowest = nums[0], best = nums[0];\\n        for (std::size_t i = 1; i \u003c nums.size(); ++i) {\\n            long long value = nums[i], fromHigh = highest  value, fromLow = lowest  value;\\n            highest = std::max({value, fromHigh, fromLow});\\n            lowest = std::min({value, fromHigh, fromLow});\\n            best = std::max(best, highest);\\n        }\\n        return static_cast\u003cint>(best);\\n    }\\n};\\n} // namespace hot100::p0152\\n\"},{\"id\":\"复杂度核算\",\"heading\":\"复杂度核算\",\"text\":\"时间 O(n)，额外空间 O(1)，无递归和输出容器。\\n\"},{\"id\":\"c-常见陷阱\",\"heading\":\"C++ 常见陷阱\",\"text\":\"- 必须先保存旧状态的两个乘积，不能更新highest后用新值算lowest。\\n- 乘法使用 long long 作为缓冲，但任意大数据仍可能溢出；保证依赖题目范围，泛化需要大整数或明确溢出策略。\\n- best 初始化首元素而不是0，否则单个负数会返回非法空区间的0。\\n\"},{\"id\":\"测试与运行\",\"heading\":\"测试与运行\",\"text\":\"完整测试源文件：2500组固定种子含负数/零的短数组，与全部连续区间乘积对拍；含负值翻转、零断开与单个负数。\\n从仓库根目录运行：\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152\\n/tmp/hot100-cpp/test_p0152\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0152_san\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\"},{\"id\":\"面试追问\",\"heading\":\"面试追问\",\"text\":\"- 如何返回最佳区间的左右下标？为何最小状态也要跟踪起点？\\n- 只有正数时这个双状态模型如何简化？\\n\"},{\"id\":\"练习与提示\",\"heading\":\"练习与提示\",\"text\":\"- 练习1：增加区间恢复。提示：每个候选携带起点，最高与最低分开保存。\\n- 练习2：分析 [-2,0,-1] 与 [-2,-1]。提示：前者不允许跨零得到2。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"152-乘积最大子数组c17-推导与实现\\\" tabindex=\\\"-1\\\">152. 乘积最大子数组：C++17 推导与实现\u003c/h1>\\n\u003cblockquote>\\n\u003cp>分类：动态规划 · 难度：MEDIUM · 官方 Hot 100 顺序：88/100\u003c/p>\\n\u003c/blockquote>\\n\u003ch2 id=\\\"题意与调用约定\\\" tabindex=\\\"-1\\\">题意与调用约定\u003c/h2>\\n\u003cp>非空数组中求连续非空子数组的最大乘积。负数和零均可能出现；不能选择空子数组来把负答案改成0。官方数据保证子数组乘积处于32位整数范围。\u003c/p>\\n\u003cp>题面与最新约束见 \u003ca href=\\\"https://leetcode.cn/problems/maximum-product-subarray/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">力扣中文官方题目\u003c/a> / \u003ca href=\\\"https://leetcode.com/problems/maximum-product-subarray/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">LeetCode 官方英文题目\u003c/a>。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\u003c/p>\\n\u003ch2 id=\\\"从直觉到优化\\\" tabindex=\\\"-1\\\">从直觉到优化\u003c/h2>\\n\u003cp>枚举全部区间要 O(n²)。最大和子数组只需一个最好结尾状态，但乘积不同：乘上负数会把最小值变成最大值。因此同时保存“以当前位置结尾”的最大乘积和最小乘积，下一项只需看当前值、旧最大乘当前、旧最小乘当前三者。\u003c/p>\\n\u003ch2 id=\\\"不变量与正确性\\\" tabindex=\\\"-1\\\">不变量与正确性\u003c/h2>\\n\u003cp>每个以i结尾的非空区间，要么只含nums[i]，要么是以i-1结尾区间追加当前项。正数乘法保持大小次序，负数逆转次序，零全部归零，所以旧最大与旧最小足以表示所有扩展极值。best再对所有结尾最大值取最大。\u003c/p>\\n\u003ch2 id=\\\"算法步骤\\\" tabindex=\\\"-1\\\">算法步骤\u003c/h2>\\n\u003col>\\n\u003cli>用首项初始化最高、最低和全局最佳，保留非空条件。\u003c/li>\\n\u003cli>先计算旧highest\u003cem>value、旧lowest\u003c/em>value。\u003c/li>\\n\u003cli>分别从三候选中取最大与最小。\u003c/li>\\n\u003cli>更新全局best，继续扫描。\u003c/li>\\n\u003c/ol>\\n\u003ch2 id=\\\"手工追踪\\\" tabindex=\\\"-1\\\">手工追踪\u003c/h2>\\n\u003cp>[-2,3,-4]：初始最高最低都-2；乘3后最高3、最低-6；乘-4后候选-4、-12、24，最高24、最低-12，全局24。负数把上一轮最差的-6翻成最好24。零会自然切断之前乘积链。\u003c/p>\\n\u003ch2 id=\\\"完整-c17-实现\\\" tabindex=\\\"-1\\\">完整 C++17 实现\u003c/h2>\\n\u003cp>以下内容来自本课 \u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0152_maximum_product_subarray.hpp\\\">可编译头文件\u003c/a>，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0152 {\\nclass Solution {\\npublic:\\n    int maxProduct(std::vector&lt;int&gt;&amp; nums) {\\n        if (nums.empty()) throw std::invalid_argument(&quot;maxProduct requires data&quot;);\\n        long long highest = nums[0], lowest = nums[0], best = nums[0];\\n        for (std::size_t i = 1; i &lt; nums.size(); ++i) {\\n            long long value = nums[i], fromHigh = highest * value, fromLow = lowest * value;\\n            highest = std::max({value, fromHigh, fromLow});\\n            lowest = std::min({value, fromHigh, fromLow});\\n            best = std::max(best, highest);\\n        }\\n        return static_cast&lt;int&gt;(best);\\n    }\\n};\\n} // namespace hot100::p0152\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"复杂度核算\\\" tabindex=\\\"-1\\\">复杂度核算\u003c/h2>\\n\u003cp>时间 O(n)，额外空间 O(1)，无递归和输出容器。\u003c/p>\\n\u003ch2 id=\\\"c-常见陷阱\\\" tabindex=\\\"-1\\\">C++ 常见陷阱\u003c/h2>\\n\u003cul>\\n\u003cli>必须先保存旧状态的两个乘积，不能更新highest后用新值算lowest。\u003c/li>\\n\u003cli>乘法使用 long long 作为缓冲，但任意大数据仍可能溢出；保证依赖题目范围，泛化需要大整数或明确溢出策略。\u003c/li>\\n\u003cli>best 初始化首元素而不是0，否则单个负数会返回非法空区间的0。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"测试与运行\\\" tabindex=\\\"-1\\\">测试与运行\u003c/h2>\\n\u003cp>\u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0152.cpp\\\">完整测试源文件\u003c/a>：2500组固定种子含负数/零的短数组，与全部连续区间乘积对拍；含负值翻转、零断开与单个负数。\u003c/p>\\n\u003cp>从仓库根目录运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>bash\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 bash 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>mkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152\\n/tmp/hot100-cpp/test_p0152\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0152_san\u003c/code>\u003c/pre>\u003c/div>\u003cp>本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\u003c/p>\\n\u003ch2 id=\\\"面试追问\\\" tabindex=\\\"-1\\\">面试追问\u003c/h2>\\n\u003cul>\\n\u003cli>如何返回最佳区间的左右下标？为何最小状态也要跟踪起点？\u003c/li>\\n\u003cli>只有正数时这个双状态模型如何简化？\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"练习与提示\\\" tabindex=\\\"-1\\\">练习与提示\u003c/h2>\\n\u003cul>\\n\u003cli>练习1：增加区间恢复。提示：每个候选携带起点，最高与最低分开保存。\u003c/li>\\n\u003cli>练习2：分析 [-2,0,-1] 与 [-2,-1]。提示：前者不允许跨零得到2。\u003c/li>\\n\u003c/ul>\\n\",\"source\":\"# 152. 乘积最大子数组：C++17 推导与实现\\n\\n> 分类：动态规划 · 难度：MEDIUM · 官方 Hot 100 顺序：88/100\\n\\n## 题意与调用约定\\n\\n非空数组中求连续非空子数组的最大乘积。负数和零均可能出现；不能选择空子数组来把负答案改成0。官方数据保证子数组乘积处于32位整数范围。\\n\\n题面与最新约束见 [力扣中文官方题目](https://leetcode.cn/problems/maximum-product-subarray/) / [LeetCode 官方英文题目](https://leetcode.com/problems/maximum-product-subarray/)。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\\n## 从直觉到优化\\n\\n枚举全部区间要 O(n²)。最大和子数组只需一个最好结尾状态，但乘积不同：乘上负数会把最小值变成最大值。因此同时保存“以当前位置结尾”的最大乘积和最小乘积，下一项只需看当前值、旧最大乘当前、旧最小乘当前三者。\\n\\n## 不变量与正确性\\n\\n每个以i结尾的非空区间，要么只含nums[i]，要么是以i-1结尾区间追加当前项。正数乘法保持大小次序，负数逆转次序，零全部归零，所以旧最大与旧最小足以表示所有扩展极值。best再对所有结尾最大值取最大。\\n\\n## 算法步骤\\n\\n1. 用首项初始化最高、最低和全局最佳，保留非空条件。\\n2. 先计算旧highest*value、旧lowest*value。\\n3. 分别从三候选中取最大与最小。\\n4. 更新全局best，继续扫描。\\n\\n## 手工追踪\\n\\n[-2,3,-4]：初始最高最低都-2；乘3后最高3、最低-6；乘-4后候选-4、-12、24，最高24、最低-12，全局24。负数把上一轮最差的-6翻成最好24。零会自然切断之前乘积链。\\n\\n## 完整 C++17 实现\\n\\n以下内容来自本课 [可编译头文件](../../../algorithms/cpp/solutions/p0152_maximum_product_subarray.hpp)，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0152 {\\nclass Solution {\\npublic:\\n    int maxProduct(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"maxProduct requires data\\\");\\n        long long highest = nums[0], lowest = nums[0], best = nums[0];\\n        for (std::size_t i = 1; i \u003c nums.size(); ++i) {\\n            long long value = nums[i], fromHigh = highest * value, fromLow = lowest * value;\\n            highest = std::max({value, fromHigh, fromLow});\\n            lowest = std::min({value, fromHigh, fromLow});\\n            best = std::max(best, highest);\\n        }\\n        return static_cast\u003cint>(best);\\n    }\\n};\\n} // namespace hot100::p0152\\n```\\n\\n## 复杂度核算\\n\\n时间 O(n)，额外空间 O(1)，无递归和输出容器。\\n\\n## C++ 常见陷阱\\n\\n- 必须先保存旧状态的两个乘积，不能更新highest后用新值算lowest。\\n- 乘法使用 long long 作为缓冲，但任意大数据仍可能溢出；保证依赖题目范围，泛化需要大整数或明确溢出策略。\\n- best 初始化首元素而不是0，否则单个负数会返回非法空区间的0。\\n\\n## 测试与运行\\n\\n[完整测试源文件](../../../algorithms/cpp/tests/test_p0152.cpp)：2500组固定种子含负数/零的短数组，与全部连续区间乘积对拍；含负值翻转、零断开与单个负数。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152\\n/tmp/hot100-cpp/test_p0152\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0152.cpp -o /tmp/hot100-cpp/test_p0152_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0152_san\\n```\\n\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\\n## 面试追问\\n\\n- 如何返回最佳区间的左右下标？为何最小状态也要跟踪起点？\\n- 只有正数时这个双状态模型如何简化？\\n\\n## 练习与提示\\n\\n- 练习1：增加区间恢复。提示：每个候选携带起点，最高与最低分开保存。\\n- 练习2：分析 [-2,0,-1] 与 [-2,-1]。提示：前者不允许跨零得到2。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0153-find-minimum-in-rotated-sorted-array.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0153-find-minimum-in-rotated-sorted-array.md\",\"title\":\"153. 寻找旋转排序数组中的最小值：C++17 推导与实现\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"二分查找\",\"difficulty\":\"MEDIUM\",\"problemId\":153,\"supplemental\":false,\"questionIds\":[\"LC153\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"非空数组是严格递增序列的旋转，返回其中最小值。允许旋转后与原数组相同；元素互异。教学实现对不满足非空前提的调用抛出异常。 题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\",\"minutes\":5,\"headings\":[{\"id\":\"153-寻找旋转排序数组中的最小值c17-推导与实现\",\"text\":\"153. 寻找旋转排序数组中的最小值：C++17 推导与实现\",\"level\":1},{\"id\":\"题意与调用约定\",\"text\":\"题意与调用约定\",\"level\":2},{\"id\":\"从直觉到优化\",\"text\":\"从直觉到优化\",\"level\":2},{\"id\":\"不变量与正确性\",\"text\":\"不变量与正确性\",\"level\":2},{\"id\":\"算法步骤\",\"text\":\"算法步骤\",\"level\":2},{\"id\":\"手工追踪\",\"text\":\"手工追踪\",\"level\":2},{\"id\":\"完整-c17-实现\",\"text\":\"完整 C++17 实现\",\"level\":2},{\"id\":\"复杂度核算\",\"text\":\"复杂度核算\",\"level\":2},{\"id\":\"c-常见陷阱\",\"text\":\"C++ 常见陷阱\",\"level\":2},{\"id\":\"测试与运行\",\"text\":\"测试与运行\",\"level\":2},{\"id\":\"面试追问\",\"text\":\"面试追问\",\"level\":2},{\"id\":\"练习与提示\",\"text\":\"练习与提示\",\"level\":2}],\"sections\":[{\"id\":\"153-寻找旋转排序数组中的最小值c17-推导与实现\",\"heading\":\"153. 寻找旋转排序数组中的最小值：C++17 推导与实现\",\"text\":\"> 分类：二分查找 · 难度：MEDIUM · 官方 Hot 100 顺序：67/100\\n\"},{\"id\":\"题意与调用约定\",\"heading\":\"题意与调用约定\",\"text\":\"非空数组是严格递增序列的旋转，返回其中最小值。允许旋转后与原数组相同；元素互异。教学实现对不满足非空前提的调用抛出异常。\\n题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\"},{\"id\":\"从直觉到优化\",\"heading\":\"从直觉到优化\",\"text\":\"线性找最小值很直接。二分需要一个能判断“最小值在哪边”的参照物，右端点正合适。中点大于右端，说明中点仍处于较大的前段，断点在右侧；中点小于右端，则中点及右端之间没有下降，最小值不在中点之后。\\n\"},{\"id\":\"不变量与正确性\",\"heading\":\"不变量与正确性\",\"text\":\"最小值下标始终在 [lo,hi]。若 nums[mid]>nums[hi]，最小值一定严格在 mid 右侧，令 lo=mid+1；否则右侧局部有序，mid 仍可能是最小值，所以令 hi=mid。区间长度每次减少，剩一项时即答案。\\n\"},{\"id\":\"算法步骤\",\"heading\":\"算法步骤\",\"text\":\"1. 建立非空闭区间，循环条件使用 lo\u003chi。\\n2. 以 nums[hi] 为参照判断中点属于高段还是低段。\\n3. 高段排除中点及左侧；低段保留中点，收缩右端。\\n4. 单点收敛后返回对应值。\\n\"},{\"id\":\"手工追踪\",\"heading\":\"手工追踪\",\"text\":\"[9,12,2,5,7]：mid=2值2 \u003c=右值7，所以 hi=2；[0,2] 的mid=1值12>2，所以 lo=2。结果2。已排序 [2,5,7] 会不断缩右端，仍正确停在下标0。\\n\"},{\"id\":\"完整-c17-实现\",\"heading\":\"完整 C++17 实现\",\"text\":\"以下内容来自本课 可编译头文件，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0153 {\\nclass Solution {\\npublic:\\n    int findMin(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"findMin requires a nonempty array\\\");\\n        int lo = 0, hi = static_cast\u003cint>(nums.size()) - 1;\\n        while (lo \u003c hi) {\\n            int mid = lo + (hi - lo) / 2;\\n            if (nums[mid] > nums[hi]) lo = mid + 1;\\n            else hi = mid;\\n        }\\n        return nums[lo];\\n    }\\n};\\n} // namespace hot100::p0153\\n\"},{\"id\":\"复杂度核算\",\"heading\":\"复杂度核算\",\"text\":\"时间 O(log n)，额外空间 O(1)。不修改输入，不分配输出容器。\\n\"},{\"id\":\"c-常见陷阱\",\"heading\":\"C++ 常见陷阱\",\"text\":\"- 写 hi=mid-1 会在中点就是最小值时删掉答案。\\n- 比较对象是当前 nums[hi]，不是固定 nums.back()；证明依赖当前区间。\\n- 重复值版遇到相等通常只能 --hi，最坏 O(n)；空输入不能随意返回 -1，因为 -1可能是合法最小值。\\n\"},{\"id\":\"测试与运行\",\"heading\":\"测试与运行\",\"text\":\"完整测试源文件：穷举长度1到40的所有旋转，验证最小值与输入未改变；含单项及空输入异常。\\n从仓库根目录运行：\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153\\n/tmp/hot100-cpp/test_p0153\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0153_san\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\"},{\"id\":\"面试追问\",\"heading\":\"面试追问\",\"text\":\"- 找旋转次数相当于寻找什么下标？\\n- 允许重复值时为什么不能承诺对数最坏复杂度？\\n\"},{\"id\":\"练习与提示\",\"heading\":\"练习与提示\",\"text\":\"- 练习1：把接口改为返回最小值下标。提示：返回收敛后的 lo。\\n- 练习2：为 [2,2,2,0,2] 设计重复值版本。提示：相等时只缩去一项，不能删半段。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"153-寻找旋转排序数组中的最小值c17-推导与实现\\\" tabindex=\\\"-1\\\">153. 寻找旋转排序数组中的最小值：C++17 推导与实现\u003c/h1>\\n\u003cblockquote>\\n\u003cp>分类：二分查找 · 难度：MEDIUM · 官方 Hot 100 顺序：67/100\u003c/p>\\n\u003c/blockquote>\\n\u003ch2 id=\\\"题意与调用约定\\\" tabindex=\\\"-1\\\">题意与调用约定\u003c/h2>\\n\u003cp>非空数组是严格递增序列的旋转，返回其中最小值。允许旋转后与原数组相同；元素互异。教学实现对不满足非空前提的调用抛出异常。\u003c/p>\\n\u003cp>题面与最新约束见 \u003ca href=\\\"https://leetcode.cn/problems/find-minimum-in-rotated-sorted-array/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">力扣中文官方题目\u003c/a> / \u003ca href=\\\"https://leetcode.com/problems/find-minimum-in-rotated-sorted-array/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">LeetCode 官方英文题目\u003c/a>。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\u003c/p>\\n\u003ch2 id=\\\"从直觉到优化\\\" tabindex=\\\"-1\\\">从直觉到优化\u003c/h2>\\n\u003cp>线性找最小值很直接。二分需要一个能判断“最小值在哪边”的参照物，右端点正合适。中点大于右端，说明中点仍处于较大的前段，断点在右侧；中点小于右端，则中点及右端之间没有下降，最小值不在中点之后。\u003c/p>\\n\u003ch2 id=\\\"不变量与正确性\\\" tabindex=\\\"-1\\\">不变量与正确性\u003c/h2>\\n\u003cp>最小值下标始终在 [lo,hi]。若 nums[mid]&gt;nums[hi]，最小值一定严格在 mid 右侧，令 lo=mid+1；否则右侧局部有序，mid 仍可能是最小值，所以令 hi=mid。区间长度每次减少，剩一项时即答案。\u003c/p>\\n\u003ch2 id=\\\"算法步骤\\\" tabindex=\\\"-1\\\">算法步骤\u003c/h2>\\n\u003col>\\n\u003cli>建立非空闭区间，循环条件使用 lo&lt;hi。\u003c/li>\\n\u003cli>以 nums[hi] 为参照判断中点属于高段还是低段。\u003c/li>\\n\u003cli>高段排除中点及左侧；低段保留中点，收缩右端。\u003c/li>\\n\u003cli>单点收敛后返回对应值。\u003c/li>\\n\u003c/ol>\\n\u003ch2 id=\\\"手工追踪\\\" tabindex=\\\"-1\\\">手工追踪\u003c/h2>\\n\u003cp>[9,12,2,5,7]：mid=2值2 &lt;=右值7，所以 hi=2；[0,2] 的mid=1值12&gt;2，所以 lo=2。结果2。已排序 [2,5,7] 会不断缩右端，仍正确停在下标0。\u003c/p>\\n\u003ch2 id=\\\"完整-c17-实现\\\" tabindex=\\\"-1\\\">完整 C++17 实现\u003c/h2>\\n\u003cp>以下内容来自本课 \u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0153_find_minimum_in_rotated_sorted_array.hpp\\\">可编译头文件\u003c/a>，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0153 {\\nclass Solution {\\npublic:\\n    int findMin(std::vector&lt;int&gt;&amp; nums) {\\n        if (nums.empty()) throw std::invalid_argument(&quot;findMin requires a nonempty array&quot;);\\n        int lo = 0, hi = static_cast&lt;int&gt;(nums.size()) - 1;\\n        while (lo &lt; hi) {\\n            int mid = lo + (hi - lo) / 2;\\n            if (nums[mid] &gt; nums[hi]) lo = mid + 1;\\n            else hi = mid;\\n        }\\n        return nums[lo];\\n    }\\n};\\n} // namespace hot100::p0153\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"复杂度核算\\\" tabindex=\\\"-1\\\">复杂度核算\u003c/h2>\\n\u003cp>时间 O(log n)，额外空间 O(1)。不修改输入，不分配输出容器。\u003c/p>\\n\u003ch2 id=\\\"c-常见陷阱\\\" tabindex=\\\"-1\\\">C++ 常见陷阱\u003c/h2>\\n\u003cul>\\n\u003cli>写 hi=mid-1 会在中点就是最小值时删掉答案。\u003c/li>\\n\u003cli>比较对象是当前 nums[hi]，不是固定 nums.back()；证明依赖当前区间。\u003c/li>\\n\u003cli>重复值版遇到相等通常只能 --hi，最坏 O(n)；空输入不能随意返回 -1，因为 -1可能是合法最小值。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"测试与运行\\\" tabindex=\\\"-1\\\">测试与运行\u003c/h2>\\n\u003cp>\u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0153.cpp\\\">完整测试源文件\u003c/a>：穷举长度1到40的所有旋转，验证最小值与输入未改变；含单项及空输入异常。\u003c/p>\\n\u003cp>从仓库根目录运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>bash\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 bash 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>mkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153\\n/tmp/hot100-cpp/test_p0153\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0153_san\u003c/code>\u003c/pre>\u003c/div>\u003cp>本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\u003c/p>\\n\u003ch2 id=\\\"面试追问\\\" tabindex=\\\"-1\\\">面试追问\u003c/h2>\\n\u003cul>\\n\u003cli>找旋转次数相当于寻找什么下标？\u003c/li>\\n\u003cli>允许重复值时为什么不能承诺对数最坏复杂度？\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"练习与提示\\\" tabindex=\\\"-1\\\">练习与提示\u003c/h2>\\n\u003cul>\\n\u003cli>练习1：把接口改为返回最小值下标。提示：返回收敛后的 lo。\u003c/li>\\n\u003cli>练习2：为 [2,2,2,0,2] 设计重复值版本。提示：相等时只缩去一项，不能删半段。\u003c/li>\\n\u003c/ul>\\n\",\"source\":\"# 153. 寻找旋转排序数组中的最小值：C++17 推导与实现\\n\\n> 分类：二分查找 · 难度：MEDIUM · 官方 Hot 100 顺序：67/100\\n\\n## 题意与调用约定\\n\\n非空数组是严格递增序列的旋转，返回其中最小值。允许旋转后与原数组相同；元素互异。教学实现对不满足非空前提的调用抛出异常。\\n\\n题面与最新约束见 [力扣中文官方题目](https://leetcode.cn/problems/find-minimum-in-rotated-sorted-array/) / [LeetCode 官方英文题目](https://leetcode.com/problems/find-minimum-in-rotated-sorted-array/)。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\\n## 从直觉到优化\\n\\n线性找最小值很直接。二分需要一个能判断“最小值在哪边”的参照物，右端点正合适。中点大于右端，说明中点仍处于较大的前段，断点在右侧；中点小于右端，则中点及右端之间没有下降，最小值不在中点之后。\\n\\n## 不变量与正确性\\n\\n最小值下标始终在 [lo,hi]。若 nums[mid]>nums[hi]，最小值一定严格在 mid 右侧，令 lo=mid+1；否则右侧局部有序，mid 仍可能是最小值，所以令 hi=mid。区间长度每次减少，剩一项时即答案。\\n\\n## 算法步骤\\n\\n1. 建立非空闭区间，循环条件使用 lo\u003chi。\\n2. 以 nums[hi] 为参照判断中点属于高段还是低段。\\n3. 高段排除中点及左侧；低段保留中点，收缩右端。\\n4. 单点收敛后返回对应值。\\n\\n## 手工追踪\\n\\n[9,12,2,5,7]：mid=2值2 \u003c=右值7，所以 hi=2；[0,2] 的mid=1值12>2，所以 lo=2。结果2。已排序 [2,5,7] 会不断缩右端，仍正确停在下标0。\\n\\n## 完整 C++17 实现\\n\\n以下内容来自本课 [可编译头文件](../../../algorithms/cpp/solutions/p0153_find_minimum_in_rotated_sorted_array.hpp)，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0153 {\\nclass Solution {\\npublic:\\n    int findMin(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"findMin requires a nonempty array\\\");\\n        int lo = 0, hi = static_cast\u003cint>(nums.size()) - 1;\\n        while (lo \u003c hi) {\\n            int mid = lo + (hi - lo) / 2;\\n            if (nums[mid] > nums[hi]) lo = mid + 1;\\n            else hi = mid;\\n        }\\n        return nums[lo];\\n    }\\n};\\n} // namespace hot100::p0153\\n```\\n\\n## 复杂度核算\\n\\n时间 O(log n)，额外空间 O(1)。不修改输入，不分配输出容器。\\n\\n## C++ 常见陷阱\\n\\n- 写 hi=mid-1 会在中点就是最小值时删掉答案。\\n- 比较对象是当前 nums[hi]，不是固定 nums.back()；证明依赖当前区间。\\n- 重复值版遇到相等通常只能 --hi，最坏 O(n)；空输入不能随意返回 -1，因为 -1可能是合法最小值。\\n\\n## 测试与运行\\n\\n[完整测试源文件](../../../algorithms/cpp/tests/test_p0153.cpp)：穷举长度1到40的所有旋转，验证最小值与输入未改变；含单项及空输入异常。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153\\n/tmp/hot100-cpp/test_p0153\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0153.cpp -o /tmp/hot100-cpp/test_p0153_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0153_san\\n```\\n\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\\n## 面试追问\\n\\n- 找旋转次数相当于寻找什么下标？\\n- 允许重复值时为什么不能承诺对数最坏复杂度？\\n\\n## 练习与提示\\n\\n- 练习1：把接口改为返回最小值下标。提示：返回收敛后的 lo。\\n- 练习2：为 [2,2,2,0,2] 设计重复值版本。提示：相等时只缩去一项，不能删半段。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0155-min-stack.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0155-min-stack.md\",\"title\":\"155. 最小栈：C++17 推导与实现\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"栈\",\"difficulty\":\"MEDIUM\",\"problemId\":155,\"supplemental\":false,\"questionIds\":[\"LC155\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"实现 push、pop、top、getMin；查询当前所有栈元素的最小值不需要扫描。官方保证 pop/top/getMin 的调用有效；这里额外给空栈调用明确异常。 题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\",\"minutes\":6,\"headings\":[{\"id\":\"155-最小栈c17-推导与实现\",\"text\":\"155. 最小栈：C++17 推导与实现\",\"level\":1},{\"id\":\"题意与调用约定\",\"text\":\"题意与调用约定\",\"level\":2},{\"id\":\"从直觉到优化\",\"text\":\"从直觉到优化\",\"level\":2},{\"id\":\"不变量与正确性\",\"text\":\"不变量与正确性\",\"level\":2},{\"id\":\"算法步骤\",\"text\":\"算法步骤\",\"level\":2},{\"id\":\"手工追踪\",\"text\":\"手工追踪\",\"level\":2},{\"id\":\"完整-c17-实现\",\"text\":\"完整 C++17 实现\",\"level\":2},{\"id\":\"复杂度核算\",\"text\":\"复杂度核算\",\"level\":2},{\"id\":\"c-常见陷阱\",\"text\":\"C++ 常见陷阱\",\"level\":2},{\"id\":\"测试与运行\",\"text\":\"测试与运行\",\"level\":2},{\"id\":\"面试追问\",\"text\":\"面试追问\",\"level\":2},{\"id\":\"练习与提示\",\"text\":\"练习与提示\",\"level\":2},{\"id\":\"实现复用与边界检查\",\"text\":\"实现复用与边界检查\",\"level\":2}],\"sections\":[{\"id\":\"155-最小栈c17-推导与实现\",\"heading\":\"155. 最小栈：C++17 推导与实现\",\"text\":\"> 分类：栈 · 难度：MEDIUM · 官方 Hot 100 顺序：70/100\\n\"},{\"id\":\"题意与调用约定\",\"heading\":\"题意与调用约定\",\"text\":\"实现 push、pop、top、getMin；查询当前所有栈元素的最小值不需要扫描。官方保证 pop/top/getMin 的调用有效；这里额外给空栈调用明确异常。\\n题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\"},{\"id\":\"从直觉到优化\",\"heading\":\"从直觉到优化\",\"text\":\"每次 getMin 扫描会使查询 O(n)。关键是 pop 必须恢复“压入当前元素之前”的最小值，所以不能只存一个全局 minimum。本实现给每个栈位置附带该前缀最小值：空间换掉重新计算。重复最小值自然得到独立快照。\\n\"},{\"id\":\"不变量与正确性\",\"heading\":\"不变量与正确性\",\"text\":\"items[k].first 是第k个栈值，items[k].second 是第0到k个值的最小值。push 使用 min(新值,旧前缀最小值) 扩展该性质；pop 直接删除最后一对，前一个快照自动恢复。故栈顶的 second 始终是当前最小值。\\n\"},{\"id\":\"算法步骤\",\"heading\":\"算法步骤\",\"text\":\"1. 每次 push 计算新前缀最小值，并把值和快照同时压入。\\n2. pop 同时移除值与该层快照。\\n3. top 读取 first，getMin 读取 second。\\n4. 对无数据的查询和弹出先执行保护检查。\\n\"},{\"id\":\"手工追踪\",\"heading\":\"手工追踪\",\"text\":\"依次 push 4,-2,-2,7，存储 [(4,4),(-2,-2),(-2,-2),(7,-2)]。弹出7和一个-2后最小值仍是-2；再次弹出-2后，剩(4,4)，getMin恢复4。无需特判重复最小值。\\n\"},{\"id\":\"完整-c17-实现\",\"heading\":\"完整 C++17 实现\",\"text\":\"以下内容来自本课 可编译头文件，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0155 {\\nclass MinStack {\\n    std::deque\u003cstd::pair\u003cint,int>> items;\\n    void requireData() const {\\n        if (items.empty()) throw std::out_of_range(\\\"empty MinStack\\\");\\n    }\\npublic:\\n    void push(int val) {\\n        int minimum = items.empty() ? val : std::min(val, items.back().second);\\n        items.emplace_back(val, minimum);\\n    }\\n    void pop() { requireData(); items.pop_back(); }\\n    int top() { requireData(); return items.back().first; }\\n    int getMin() { requireData(); return items.back().second; }\\n};\\n} // namespace hot100::p0155\\n\"},{\"id\":\"复杂度核算\",\"heading\":\"复杂度核算\",\"text\":\"push/pop/top/getMin 在标准容器复杂度模型下均为 O(1)；deque 两端插入不需要整体迁移元素。总空间 O(n)，每项两个 int。若改用 vector，push 只有摊还 O(1)，扩容单次为 O(n)，应准确说明区别。\\n\"},{\"id\":\"c-常见陷阱\",\"heading\":\"C++ 常见陷阱\",\"text\":\"- 差值压栈方案 val-min 在 INT_MIN 与 INT_MAX 间可能溢出；快照法没有算术差值。\\n- deque 两端插入可能使迭代器失效；本实现不跨 push 保存迭代器，也不在 pop 后引用已删元素。\\n- 不要用初始最小值0，正数首元素会被错误比较；空栈首项直接使用 val。\\n\"},{\"id\":\"测试与运行\",\"heading\":\"测试与运行\",\"text\":\"完整测试源文件：20000次固定种子随机压入/弹出操作，每次与普通vector的栈顶和扫描最小值核对；专测重复最小、极值与空查询异常。\\n从仓库根目录运行：\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155\\n/tmp/hot100-cpp/test_p0155\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0155_san\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\"},{\"id\":\"面试追问\",\"heading\":\"面试追问\",\"text\":\"- 如何同时提供 getMax？每层再保存一个前缀最大值。\\n- 只保存“最小值变化”的辅助栈能节约哪些输入的空间？重复最小值怎样恢复？\\n\"},{\"id\":\"练习与提示\",\"heading\":\"练习与提示\",\"text\":\"- 练习1：实现两个栈版并对重复最小值测试。提示：相等时也要压入辅助栈，或保存出现次数。\\n- 练习2：做支持撤销最后一次 push/pop 的版本。提示：区分状态快照与操作日志。\\n\"},{\"id\":\"实现复用与边界检查\",\"heading\":\"实现复用与边界检查\",\"text\":\"C++17 不保证 long 为64位，LLP64 平台的 val-min 可溢出。差值栈仍需每项记录；此实现用前缀最小值快照，研究差值方案时应明确64位中间类型。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"155-最小栈c17-推导与实现\\\" tabindex=\\\"-1\\\">155. 最小栈：C++17 推导与实现\u003c/h1>\\n\u003cblockquote>\\n\u003cp>分类：栈 · 难度：MEDIUM · 官方 Hot 100 顺序：70/100\u003c/p>\\n\u003c/blockquote>\\n\u003ch2 id=\\\"题意与调用约定\\\" tabindex=\\\"-1\\\">题意与调用约定\u003c/h2>\\n\u003cp>实现 push、pop、top、getMin；查询当前所有栈元素的最小值不需要扫描。官方保证 pop/top/getMin 的调用有效；这里额外给空栈调用明确异常。\u003c/p>\\n\u003cp>题面与最新约束见 \u003ca href=\\\"https://leetcode.cn/problems/min-stack/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">力扣中文官方题目\u003c/a> / \u003ca href=\\\"https://leetcode.com/problems/min-stack/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">LeetCode 官方英文题目\u003c/a>。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\u003c/p>\\n\u003ch2 id=\\\"从直觉到优化\\\" tabindex=\\\"-1\\\">从直觉到优化\u003c/h2>\\n\u003cp>每次 getMin 扫描会使查询 O(n)。关键是 pop 必须恢复“压入当前元素之前”的最小值，所以不能只存一个全局 minimum。本实现给每个栈位置附带该前缀最小值：空间换掉重新计算。重复最小值自然得到独立快照。\u003c/p>\\n\u003ch2 id=\\\"不变量与正确性\\\" tabindex=\\\"-1\\\">不变量与正确性\u003c/h2>\\n\u003cp>items[k].first 是第k个栈值，items[k].second 是第0到k个值的最小值。push 使用 min(新值,旧前缀最小值) 扩展该性质；pop 直接删除最后一对，前一个快照自动恢复。故栈顶的 second 始终是当前最小值。\u003c/p>\\n\u003ch2 id=\\\"算法步骤\\\" tabindex=\\\"-1\\\">算法步骤\u003c/h2>\\n\u003col>\\n\u003cli>每次 push 计算新前缀最小值，并把值和快照同时压入。\u003c/li>\\n\u003cli>pop 同时移除值与该层快照。\u003c/li>\\n\u003cli>top 读取 first，getMin 读取 second。\u003c/li>\\n\u003cli>对无数据的查询和弹出先执行保护检查。\u003c/li>\\n\u003c/ol>\\n\u003ch2 id=\\\"手工追踪\\\" tabindex=\\\"-1\\\">手工追踪\u003c/h2>\\n\u003cp>依次 push 4,-2,-2,7，存储 [(4,4),(-2,-2),(-2,-2),(7,-2)]。弹出7和一个-2后最小值仍是-2；再次弹出-2后，剩(4,4)，getMin恢复4。无需特判重复最小值。\u003c/p>\\n\u003ch2 id=\\\"完整-c17-实现\\\" tabindex=\\\"-1\\\">完整 C++17 实现\u003c/h2>\\n\u003cp>以下内容来自本课 \u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0155_min_stack.hpp\\\">可编译头文件\u003c/a>，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0155 {\\nclass MinStack {\\n    std::deque&lt;std::pair&lt;int,int&gt;&gt; items;\\n    void requireData() const {\\n        if (items.empty()) throw std::out_of_range(&quot;empty MinStack&quot;);\\n    }\\npublic:\\n    void push(int val) {\\n        int minimum = items.empty() ? val : std::min(val, items.back().second);\\n        items.emplace_back(val, minimum);\\n    }\\n    void pop() { requireData(); items.pop_back(); }\\n    int top() { requireData(); return items.back().first; }\\n    int getMin() { requireData(); return items.back().second; }\\n};\\n} // namespace hot100::p0155\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"复杂度核算\\\" tabindex=\\\"-1\\\">复杂度核算\u003c/h2>\\n\u003cp>push/pop/top/getMin 在标准容器复杂度模型下均为 O(1)；deque 两端插入不需要整体迁移元素。总空间 O(n)，每项两个 int。若改用 vector，push 只有摊还 O(1)，扩容单次为 O(n)，应准确说明区别。\u003c/p>\\n\u003ch2 id=\\\"c-常见陷阱\\\" tabindex=\\\"-1\\\">C++ 常见陷阱\u003c/h2>\\n\u003cul>\\n\u003cli>差值压栈方案 val-min 在 INT_MIN 与 INT_MAX 间可能溢出；快照法没有算术差值。\u003c/li>\\n\u003cli>deque 两端插入可能使迭代器失效；本实现不跨 push 保存迭代器，也不在 pop 后引用已删元素。\u003c/li>\\n\u003cli>不要用初始最小值0，正数首元素会被错误比较；空栈首项直接使用 val。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"测试与运行\\\" tabindex=\\\"-1\\\">测试与运行\u003c/h2>\\n\u003cp>\u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0155.cpp\\\">完整测试源文件\u003c/a>：20000次固定种子随机压入/弹出操作，每次与普通vector的栈顶和扫描最小值核对；专测重复最小、极值与空查询异常。\u003c/p>\\n\u003cp>从仓库根目录运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>bash\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 bash 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>mkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155\\n/tmp/hot100-cpp/test_p0155\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0155_san\u003c/code>\u003c/pre>\u003c/div>\u003cp>本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\u003c/p>\\n\u003ch2 id=\\\"面试追问\\\" tabindex=\\\"-1\\\">面试追问\u003c/h2>\\n\u003cul>\\n\u003cli>如何同时提供 getMax？每层再保存一个前缀最大值。\u003c/li>\\n\u003cli>只保存“最小值变化”的辅助栈能节约哪些输入的空间？重复最小值怎样恢复？\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"练习与提示\\\" tabindex=\\\"-1\\\">练习与提示\u003c/h2>\\n\u003cul>\\n\u003cli>练习1：实现两个栈版并对重复最小值测试。提示：相等时也要压入辅助栈，或保存出现次数。\u003c/li>\\n\u003cli>练习2：做支持撤销最后一次 push/pop 的版本。提示：区分状态快照与操作日志。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"实现复用与边界检查\\\" tabindex=\\\"-1\\\">实现复用与边界检查\u003c/h2>\\n\u003cp>C++17 不保证 long 为64位，LLP64 平台的 val-min 可溢出。差值栈仍需每项记录；此实现用前缀最小值快照，研究差值方案时应明确64位中间类型。\u003c/p>\\n\",\"source\":\"# 155. 最小栈：C++17 推导与实现\\n\\n> 分类：栈 · 难度：MEDIUM · 官方 Hot 100 顺序：70/100\\n\\n## 题意与调用约定\\n\\n实现 push、pop、top、getMin；查询当前所有栈元素的最小值不需要扫描。官方保证 pop/top/getMin 的调用有效；这里额外给空栈调用明确异常。\\n\\n题面与最新约束见 [力扣中文官方题目](https://leetcode.cn/problems/min-stack/) / [LeetCode 官方英文题目](https://leetcode.com/problems/min-stack/)。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\\n## 从直觉到优化\\n\\n每次 getMin 扫描会使查询 O(n)。关键是 pop 必须恢复“压入当前元素之前”的最小值，所以不能只存一个全局 minimum。本实现给每个栈位置附带该前缀最小值：空间换掉重新计算。重复最小值自然得到独立快照。\\n\\n## 不变量与正确性\\n\\nitems[k].first 是第k个栈值，items[k].second 是第0到k个值的最小值。push 使用 min(新值,旧前缀最小值) 扩展该性质；pop 直接删除最后一对，前一个快照自动恢复。故栈顶的 second 始终是当前最小值。\\n\\n## 算法步骤\\n\\n1. 每次 push 计算新前缀最小值，并把值和快照同时压入。\\n2. pop 同时移除值与该层快照。\\n3. top 读取 first，getMin 读取 second。\\n4. 对无数据的查询和弹出先执行保护检查。\\n\\n## 手工追踪\\n\\n依次 push 4,-2,-2,7，存储 [(4,4),(-2,-2),(-2,-2),(7,-2)]。弹出7和一个-2后最小值仍是-2；再次弹出-2后，剩(4,4)，getMin恢复4。无需特判重复最小值。\\n\\n## 完整 C++17 实现\\n\\n以下内容来自本课 [可编译头文件](../../../algorithms/cpp/solutions/p0155_min_stack.hpp)，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0155 {\\nclass MinStack {\\n    std::deque\u003cstd::pair\u003cint,int>> items;\\n    void requireData() const {\\n        if (items.empty()) throw std::out_of_range(\\\"empty MinStack\\\");\\n    }\\npublic:\\n    void push(int val) {\\n        int minimum = items.empty() ? val : std::min(val, items.back().second);\\n        items.emplace_back(val, minimum);\\n    }\\n    void pop() { requireData(); items.pop_back(); }\\n    int top() { requireData(); return items.back().first; }\\n    int getMin() { requireData(); return items.back().second; }\\n};\\n} // namespace hot100::p0155\\n```\\n\\n## 复杂度核算\\n\\npush/pop/top/getMin 在标准容器复杂度模型下均为 O(1)；deque 两端插入不需要整体迁移元素。总空间 O(n)，每项两个 int。若改用 vector，push 只有摊还 O(1)，扩容单次为 O(n)，应准确说明区别。\\n\\n## C++ 常见陷阱\\n\\n- 差值压栈方案 val-min 在 INT_MIN 与 INT_MAX 间可能溢出；快照法没有算术差值。\\n- deque 两端插入可能使迭代器失效；本实现不跨 push 保存迭代器，也不在 pop 后引用已删元素。\\n- 不要用初始最小值0，正数首元素会被错误比较；空栈首项直接使用 val。\\n\\n## 测试与运行\\n\\n[完整测试源文件](../../../algorithms/cpp/tests/test_p0155.cpp)：20000次固定种子随机压入/弹出操作，每次与普通vector的栈顶和扫描最小值核对；专测重复最小、极值与空查询异常。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155\\n/tmp/hot100-cpp/test_p0155\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0155.cpp -o /tmp/hot100-cpp/test_p0155_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0155_san\\n```\\n\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\\n## 面试追问\\n\\n- 如何同时提供 getMax？每层再保存一个前缀最大值。\\n- 只保存“最小值变化”的辅助栈能节约哪些输入的空间？重复最小值怎样恢复？\\n\\n## 练习与提示\\n\\n- 练习1：实现两个栈版并对重复最小值测试。提示：相等时也要压入辅助栈，或保存出现次数。\\n- 练习2：做支持撤销最后一次 push/pop 的版本。提示：区分状态快照与操作日志。\\n\\n## 实现复用与边界检查\\n\\nC++17 不保证 long 为64位，LLP64 平台的 val-min 可溢出。差值栈仍需每项记录；此实现用前缀最小值快照，研究差值方案时应明确64位中间类型。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0160-intersection-of-two-linked-lists.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0160-intersection-of-two-linked-lists.md\",\"title\":\"160. 相交链表 · C++17\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"链表\",\"difficulty\":\"EASY\",\"problemId\":160,\"supplemental\":false,\"questionIds\":[\"LC160\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"> 学习位置：链表 · 第 1 课。难度：EASY。这是一份独立编写的学习课，不是在线提交通过声明。 官方题目 · 本课用简短契约与独立推演讲解，完整输入约束以官方题页为准。\",\"minutes\":6,\"headings\":[{\"id\":\"160-相交链表-c17\",\"text\":\"160. 相交链表 · C++17\",\"level\":1},{\"id\":\"1-先说清输入输出与修改边界\",\"text\":\"1. 先说清输入、输出与修改边界\",\"level\":2},{\"id\":\"2-从直觉到可用方案\",\"text\":\"2. 从直觉到可用方案\",\"level\":2},{\"id\":\"3-为什么正确抓住不变量\",\"text\":\"3. 为什么正确：抓住不变量\",\"level\":2},{\"id\":\"4-动手过程\",\"text\":\"4. 动手过程\",\"level\":2},{\"id\":\"5-原创例子逐步追踪\",\"text\":\"5. 原创例子逐步追踪\",\"level\":2},{\"id\":\"6-时间栈与输出空间分别算\",\"text\":\"6. 时间、栈与输出空间分别算\",\"level\":2},{\"id\":\"7-c17实现与所有权\",\"text\":\"7. C++17实现与所有权\",\"level\":2},{\"id\":\"实现复用与边界检查\",\"text\":\"实现复用与边界检查\",\"level\":2},{\"id\":\"9-本地验证\",\"text\":\"9. 本地验证\",\"level\":2},{\"id\":\"10-面试延伸\",\"text\":\"10. 面试延伸\",\"level\":2},{\"id\":\"11-两道练习与提示\",\"text\":\"11. 两道练习与提示\",\"level\":2}],\"sections\":[{\"id\":\"160-相交链表-c17\",\"heading\":\"160. 相交链表 · C++17\",\"text\":\"> 学习位置：链表 · 第 1 课。难度：EASY。这是一份独立编写的学习课，不是在线提交通过声明。\\n官方题目 · 本课用简短契约与独立推演讲解，完整输入约束以官方题页为准。\\n\"},{\"id\":\"1-先说清输入输出与修改边界\",\"heading\":\"1. 先说清输入、输出与修改边界\",\"text\":\"两个无环单链表可能共用同一段尾链。返回第一个共用节点的地址；没有共用节点则返回 nullptr。值相同不构成相交，输入结构不允许被改动。\\n\"},{\"id\":\"2-从直觉到可用方案\",\"heading\":\"2. 从直觉到可用方案\",\"text\":\"把 A 的每个节点地址放进集合，再沿 B 寻找第一个命中点，思路直接，但额外空间与 A 的长度有关。真正的障碍不是查找速度，而是两个起点离公共尾链的距离不同。\\n设两条链长度为 m、n，让指针 a 走 A 后走 B，指针 b 走 B 后走 A。它们都补走了对方的独有前缀，路程差便被抵消。无需实际拼接链表，只在指针为空时切换头指针。\\n\"},{\"id\":\"3-为什么正确抓住不变量\",\"heading\":\"3. 为什么正确：抓住不变量\",\"text\":\"若存在公共尾段长度 c，独有前缀分别长 x=m-c、y=n-c。第一次进入公共尾段可能不同步；切换之后，a 经历 x+c+y，b 经历 y+c+x，同一步到达公共尾段入口。若不相交，两个指针最终在 nullptr 相等。循环比较的是地址，因此既不会把同值节点当成相交，也不会跨过第一个共同节点才停止。\\n\"},{\"id\":\"4-动手过程\",\"heading\":\"4. 动手过程\",\"text\":\"1. 把两个游标分别放在 headA、headB。\\n2. 只要地址不同，各自推进一步；遇到 nullptr 时改走另一个链表的头。\\n3. 地址相等时返回该地址。nullptr 也是合法的共同终点。\\n4. 不保存长度，不修改任何 next。\\n\"},{\"id\":\"5-原创例子逐步追踪\",\"heading\":\"5. 原创例子逐步追踪\",\"text\":\"A 为 8→3→C，B 为 5→6→1→C，公共段 C 为 9→4。两链独有前缀长度分别是 2、3。第一次走到 9 不同步；a 走完 A 后补上 B 的三节点前缀，b 走完 B 后补上 A 的两节点前缀，最终同时指向同一个 9。若把两条链上的 9 分别单独分配，即使所有值相同，最终答案也会是 nullptr。\\n\"},{\"id\":\"6-时间栈与输出空间分别算\",\"heading\":\"6. 时间、栈与输出空间分别算\",\"text\":\"时间 O(m+n)，每个游标最多遍历两条链。辅助空间 O(1)，没有递归栈，也没有新分配的输出节点。返回值只是借用输入节点的一个地址。\\n\"},{\"id\":\"7-c17实现与所有权\",\"heading\":\"7. C++17实现与所有权\",\"text\":\"- 必须写 a == b，不能写 a->val == b->val。\\n- 先处理空指针再读取 next；三目表达式在这里避免解引用空指针。\\n- 这套证明依赖无环前提。有环时可能无法终止，不能直接套用。\\n- 不拥有输入节点，不能 delete 返回节点；调用者管理两条链共享节点的生命周期。\\n下面是本仓库完整的头文件实现；support.hpp只提供标准库包含与题目节点声明，算法自身不依赖测试工具。在线评测通常已提供节点类型，提交时保留对应类并使用评测环境要求的作用域。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0160 {\\nclass Solution {\\npublic:\\n    ListNode getIntersectionNode(ListNode headA, ListNode headB) {\\n        ListNode a = headA;\\n        ListNode b = headB;\\n        while (a != b) {\\n            a = a ? a->next : headB;\\n            b = b ? b->next : headA;\\n        }\\n        return a;\\n    }\\n};\\n} // namespace hot100::p0160\\n查看可编译源文件 · 查看完整测试\\n\"},{\"id\":\"实现复用与边界检查\",\"heading\":\"实现复用与边界检查\",\"text\":\"长度对齐与换头法都在消除独有前缀的长度差，适用于无环链表。比较的是节点身份；不同值序列不能代替相交关系。\\n\"},{\"id\":\"9-本地验证\",\"heading\":\"9. 本地验证\",\"text\":\"空链、独立同值单节点、头相同，以及49种独有前缀长度组合，共享尾节点按地址核对。 测试采用固定种子，可复现每轮输入。断言针对返回值，也针对应保持的地址、连接或输入状态。内存由arena或对应destroy工具明确回收。本地测试通过仅说明这些可复现用例通过，不等于完整在线评测结论。\\n从仓库根目录运行：\\nmkdir -p /tmp/hot100-cpp\\nc++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160\\n/tmp/hot100-cpp/test_p0160\\n# 编译器支持时，再检查地址、未定义行为与泄漏\\nc++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160_san\\nASAN_OPTIONS=detect_leaks=1 /tmp/hot100-cpp/test_p0160_san\\n# 若执行环境在ptrace下明确拒绝LeakSanitizer，可仅运行地址/UB检查：\\n# ASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0160_san\\n\"},{\"id\":\"10-面试延伸\",\"heading\":\"10. 面试延伸\",\"text\":\"- 如果有一个链表带环，哪些相交情形需要分开讨论？先分别求环入口，再讨论入口相同或不同。\\n- 为什么不能给链表 A 的尾部临时接上 B，再检测环？可以构造方法，但会修改共享结构，异常或并发读取时恢复更困难。\\n\"},{\"id\":\"11-两道练习与提示\",\"heading\":\"11. 两道练习与提示\",\"text\":\"1. 改写为长度对齐版本，再与换头版做随机交叉检查。提示：长链先走 abs(m-n) 步，之后同步前进。\\n2. 列出“两个头相同、一个头为空、两个独立单节点”的指针轨迹。提示：把 nullptr 也写成轨迹中的一个状态。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"160-相交链表-c17\\\" tabindex=\\\"-1\\\">160. 相交链表 · C++17\u003c/h1>\\n\u003cblockquote>\\n\u003cp>学习位置：链表 · 第 1 课。难度：EASY。这是一份独立编写的学习课，不是在线提交通过声明。\u003c/p>\\n\u003c/blockquote>\\n\u003cp>\u003ca href=\\\"https://leetcode.cn/problems/intersection-of-two-linked-lists/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">官方题目\u003c/a> · 本课用简短契约与独立推演讲解，完整输入约束以官方题页为准。\u003c/p>\\n\u003ch2 id=\\\"1-先说清输入输出与修改边界\\\" tabindex=\\\"-1\\\">1. 先说清输入、输出与修改边界\u003c/h2>\\n\u003cp>两个无环单链表可能共用同一段尾链。返回第一个共用节点的地址；没有共用节点则返回 nullptr。值相同不构成相交，输入结构不允许被改动。\u003c/p>\\n\u003ch2 id=\\\"2-从直觉到可用方案\\\" tabindex=\\\"-1\\\">2. 从直觉到可用方案\u003c/h2>\\n\u003cp>把 A 的每个节点地址放进集合，再沿 B 寻找第一个命中点，思路直接，但额外空间与 A 的长度有关。真正的障碍不是查找速度，而是两个起点离公共尾链的距离不同。\u003c/p>\\n\u003cp>设两条链长度为 m、n，让指针 a 走 A 后走 B，指针 b 走 B 后走 A。它们都补走了对方的独有前缀，路程差便被抵消。无需实际拼接链表，只在指针为空时切换头指针。\u003c/p>\\n\u003ch2 id=\\\"3-为什么正确抓住不变量\\\" tabindex=\\\"-1\\\">3. 为什么正确：抓住不变量\u003c/h2>\\n\u003cp>若存在公共尾段长度 c，独有前缀分别长 x=m-c、y=n-c。第一次进入公共尾段可能不同步；切换之后，a 经历 x+c+y，b 经历 y+c+x，同一步到达公共尾段入口。若不相交，两个指针最终在 nullptr 相等。循环比较的是地址，因此既不会把同值节点当成相交，也不会跨过第一个共同节点才停止。\u003c/p>\\n\u003ch2 id=\\\"4-动手过程\\\" tabindex=\\\"-1\\\">4. 动手过程\u003c/h2>\\n\u003col>\\n\u003cli>把两个游标分别放在 headA、headB。\u003c/li>\\n\u003cli>只要地址不同，各自推进一步；遇到 nullptr 时改走另一个链表的头。\u003c/li>\\n\u003cli>地址相等时返回该地址。nullptr 也是合法的共同终点。\u003c/li>\\n\u003cli>不保存长度，不修改任何 next。\u003c/li>\\n\u003c/ol>\\n\u003ch2 id=\\\"5-原创例子逐步追踪\\\" tabindex=\\\"-1\\\">5. 原创例子逐步追踪\u003c/h2>\\n\u003cp>A 为 8→3→C，B 为 5→6→1→C，公共段 C 为 9→4。两链独有前缀长度分别是 2、3。第一次走到 9 不同步；a 走完 A 后补上 B 的三节点前缀，b 走完 B 后补上 A 的两节点前缀，最终同时指向同一个 9。若把两条链上的 9 分别单独分配，即使所有值相同，最终答案也会是 nullptr。\u003c/p>\\n\u003ch2 id=\\\"6-时间栈与输出空间分别算\\\" tabindex=\\\"-1\\\">6. 时间、栈与输出空间分别算\u003c/h2>\\n\u003cp>时间 O(m+n)，每个游标最多遍历两条链。辅助空间 O(1)，没有递归栈，也没有新分配的输出节点。返回值只是借用输入节点的一个地址。\u003c/p>\\n\u003ch2 id=\\\"7-c17实现与所有权\\\" tabindex=\\\"-1\\\">7. C++17实现与所有权\u003c/h2>\\n\u003cul>\\n\u003cli>必须写 a == b，不能写 a-&gt;val == b-&gt;val。\u003c/li>\\n\u003cli>先处理空指针再读取 next；三目表达式在这里避免解引用空指针。\u003c/li>\\n\u003cli>这套证明依赖无环前提。有环时可能无法终止，不能直接套用。\u003c/li>\\n\u003cli>不拥有输入节点，不能 delete 返回节点；调用者管理两条链共享节点的生命周期。\u003c/li>\\n\u003c/ul>\\n\u003cp>下面是本仓库完整的头文件实现；support.hpp只提供标准库包含与题目节点声明，算法自身不依赖测试工具。在线评测通常已提供节点类型，提交时保留对应类并使用评测环境要求的作用域。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0160 {\\nclass Solution {\\npublic:\\n    ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {\\n        ListNode* a = headA;\\n        ListNode* b = headB;\\n        while (a != b) {\\n            a = a ? a-&gt;next : headB;\\n            b = b ? b-&gt;next : headA;\\n        }\\n        return a;\\n    }\\n};\\n} // namespace hot100::p0160\u003c/code>\u003c/pre>\u003c/div>\u003cp>\u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0160_intersection_of_two_linked_lists.hpp\\\">查看可编译源文件\u003c/a> · \u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0160.cpp\\\">查看完整测试\u003c/a>\u003c/p>\\n\u003ch2 id=\\\"实现复用与边界检查\\\" tabindex=\\\"-1\\\">实现复用与边界检查\u003c/h2>\\n\u003cp>长度对齐与换头法都在消除独有前缀的长度差，适用于无环链表。比较的是节点身份；不同值序列不能代替相交关系。\u003c/p>\\n\u003ch2 id=\\\"9-本地验证\\\" tabindex=\\\"-1\\\">9. 本地验证\u003c/h2>\\n\u003cp>空链、独立同值单节点、头相同，以及49种独有前缀长度组合，共享尾节点按地址核对。 测试采用固定种子，可复现每轮输入。断言针对返回值，也针对应保持的地址、连接或输入状态。内存由arena或对应destroy工具明确回收。本地测试通过仅说明这些可复现用例通过，不等于完整在线评测结论。\u003c/p>\\n\u003cp>从仓库根目录运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>bash\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 bash 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>mkdir -p /tmp/hot100-cpp\\nc++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160\\n/tmp/hot100-cpp/test_p0160\\n# 编译器支持时，再检查地址、未定义行为与泄漏\\nc++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160_san\\nASAN_OPTIONS=detect_leaks=1 /tmp/hot100-cpp/test_p0160_san\\n# 若执行环境在ptrace下明确拒绝LeakSanitizer，可仅运行地址/UB检查：\\n# ASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0160_san\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"10-面试延伸\\\" tabindex=\\\"-1\\\">10. 面试延伸\u003c/h2>\\n\u003cul>\\n\u003cli>如果有一个链表带环，哪些相交情形需要分开讨论？先分别求环入口，再讨论入口相同或不同。\u003c/li>\\n\u003cli>为什么不能给链表 A 的尾部临时接上 B，再检测环？可以构造方法，但会修改共享结构，异常或并发读取时恢复更困难。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"11-两道练习与提示\\\" tabindex=\\\"-1\\\">11. 两道练习与提示\u003c/h2>\\n\u003col>\\n\u003cli>改写为长度对齐版本，再与换头版做随机交叉检查。提示：长链先走 abs(m-n) 步，之后同步前进。\u003c/li>\\n\u003cli>列出“两个头相同、一个头为空、两个独立单节点”的指针轨迹。提示：把 nullptr 也写成轨迹中的一个状态。\u003c/li>\\n\u003c/ol>\\n\",\"source\":\"# 160. 相交链表 · C++17\\n\\n> 学习位置：链表 · 第 1 课。难度：EASY。这是一份独立编写的学习课，不是在线提交通过声明。\\n\\n[官方题目](https://leetcode.cn/problems/intersection-of-two-linked-lists/) · 本课用简短契约与独立推演讲解，完整输入约束以官方题页为准。\\n\\n## 1. 先说清输入、输出与修改边界\\n\\n两个无环单链表可能共用同一段尾链。返回第一个共用节点的地址；没有共用节点则返回 nullptr。值相同不构成相交，输入结构不允许被改动。\\n\\n## 2. 从直觉到可用方案\\n\\n把 A 的每个节点地址放进集合，再沿 B 寻找第一个命中点，思路直接，但额外空间与 A 的长度有关。真正的障碍不是查找速度，而是两个起点离公共尾链的距离不同。\\n\\n设两条链长度为 m、n，让指针 a 走 A 后走 B，指针 b 走 B 后走 A。它们都补走了对方的独有前缀，路程差便被抵消。无需实际拼接链表，只在指针为空时切换头指针。\\n\\n## 3. 为什么正确：抓住不变量\\n\\n若存在公共尾段长度 c，独有前缀分别长 x=m-c、y=n-c。第一次进入公共尾段可能不同步；切换之后，a 经历 x+c+y，b 经历 y+c+x，同一步到达公共尾段入口。若不相交，两个指针最终在 nullptr 相等。循环比较的是地址，因此既不会把同值节点当成相交，也不会跨过第一个共同节点才停止。\\n\\n## 4. 动手过程\\n\\n1. 把两个游标分别放在 headA、headB。\\n2. 只要地址不同，各自推进一步；遇到 nullptr 时改走另一个链表的头。\\n3. 地址相等时返回该地址。nullptr 也是合法的共同终点。\\n4. 不保存长度，不修改任何 next。\\n\\n## 5. 原创例子逐步追踪\\n\\nA 为 8→3→C，B 为 5→6→1→C，公共段 C 为 9→4。两链独有前缀长度分别是 2、3。第一次走到 9 不同步；a 走完 A 后补上 B 的三节点前缀，b 走完 B 后补上 A 的两节点前缀，最终同时指向同一个 9。若把两条链上的 9 分别单独分配，即使所有值相同，最终答案也会是 nullptr。\\n\\n## 6. 时间、栈与输出空间分别算\\n\\n时间 O(m+n)，每个游标最多遍历两条链。辅助空间 O(1)，没有递归栈，也没有新分配的输出节点。返回值只是借用输入节点的一个地址。\\n\\n## 7. C++17实现与所有权\\n\\n- 必须写 a == b，不能写 a->val == b->val。\\n- 先处理空指针再读取 next；三目表达式在这里避免解引用空指针。\\n- 这套证明依赖无环前提。有环时可能无法终止，不能直接套用。\\n- 不拥有输入节点，不能 delete 返回节点；调用者管理两条链共享节点的生命周期。\\n\\n下面是本仓库完整的头文件实现；support.hpp只提供标准库包含与题目节点声明，算法自身不依赖测试工具。在线评测通常已提供节点类型，提交时保留对应类并使用评测环境要求的作用域。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0160 {\\nclass Solution {\\npublic:\\n    ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {\\n        ListNode* a = headA;\\n        ListNode* b = headB;\\n        while (a != b) {\\n            a = a ? a->next : headB;\\n            b = b ? b->next : headA;\\n        }\\n        return a;\\n    }\\n};\\n} // namespace hot100::p0160\\n```\\n\\n[查看可编译源文件](../../../algorithms/cpp/solutions/p0160_intersection_of_two_linked_lists.hpp) · [查看完整测试](../../../algorithms/cpp/tests/test_p0160.cpp)\\n\\n## 实现复用与边界检查\\n\\n长度对齐与换头法都在消除独有前缀的长度差，适用于无环链表。比较的是节点身份；不同值序列不能代替相交关系。\\n\\n## 9. 本地验证\\n\\n空链、独立同值单节点、头相同，以及49种独有前缀长度组合，共享尾节点按地址核对。 测试采用固定种子，可复现每轮输入。断言针对返回值，也针对应保持的地址、连接或输入状态。内存由arena或对应destroy工具明确回收。本地测试通过仅说明这些可复现用例通过，不等于完整在线评测结论。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\nc++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160\\n/tmp/hot100-cpp/test_p0160\\n# 编译器支持时，再检查地址、未定义行为与泄漏\\nc++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0160.cpp -o /tmp/hot100-cpp/test_p0160_san\\nASAN_OPTIONS=detect_leaks=1 /tmp/hot100-cpp/test_p0160_san\\n# 若执行环境在ptrace下明确拒绝LeakSanitizer，可仅运行地址/UB检查：\\n# ASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0160_san\\n```\\n\\n## 10. 面试延伸\\n\\n- 如果有一个链表带环，哪些相交情形需要分开讨论？先分别求环入口，再讨论入口相同或不同。\\n- 为什么不能给链表 A 的尾部临时接上 B，再检测环？可以构造方法，但会修改共享结构，异常或并发读取时恢复更困难。\\n\\n## 11. 两道练习与提示\\n\\n1. 改写为长度对齐版本，再与换头版做随机交叉检查。提示：长链先走 abs(m-n) 步，之后同步前进。\\n2. 列出“两个头相同、一个头为空、两个独立单节点”的指针轨迹。提示：把 nullptr 也写成轨迹中的一个状态。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0169-majority-element.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0169-majority-element.md\",\"title\":\"169. 多数元素：C++17 推导与实现\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"技巧\",\"difficulty\":\"EASY\",\"problemId\":169,\"supplemental\":false,\"questionIds\":[\"LC169\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"非空数组保证存在出现次数严格超过一半的值，返回它。不是“出现次数最多”而是“超过 n/2”；若去掉存在保证，必须增加验证。 题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\",\"minutes\":5,\"headings\":[{\"id\":\"169-多数元素c17-推导与实现\",\"text\":\"169. 多数元素：C++17 推导与实现\",\"level\":1},{\"id\":\"题意与调用约定\",\"text\":\"题意与调用约定\",\"level\":2},{\"id\":\"从直觉到优化\",\"text\":\"从直觉到优化\",\"level\":2},{\"id\":\"不变量与正确性\",\"text\":\"不变量与正确性\",\"level\":2},{\"id\":\"算法步骤\",\"text\":\"算法步骤\",\"level\":2},{\"id\":\"手工追踪\",\"text\":\"手工追踪\",\"level\":2},{\"id\":\"完整-c17-实现\",\"text\":\"完整 C++17 实现\",\"level\":2},{\"id\":\"复杂度核算\",\"text\":\"复杂度核算\",\"level\":2},{\"id\":\"c-常见陷阱\",\"text\":\"C++ 常见陷阱\",\"level\":2},{\"id\":\"测试与运行\",\"text\":\"测试与运行\",\"level\":2},{\"id\":\"面试追问\",\"text\":\"面试追问\",\"level\":2},{\"id\":\"练习与提示\",\"text\":\"练习与提示\",\"level\":2}],\"sections\":[{\"id\":\"169-多数元素c17-推导与实现\",\"heading\":\"169. 多数元素：C++17 推导与实现\",\"text\":\"> 分类：技巧 · 难度：EASY · 官方 Hot 100 顺序：97/100\\n\"},{\"id\":\"题意与调用约定\",\"heading\":\"题意与调用约定\",\"text\":\"非空数组保证存在出现次数严格超过一半的值，返回它。不是“出现次数最多”而是“超过 n/2”；若去掉存在保证，必须增加验证。\\n题面与最新约束见 力扣中文官方题目 / LeetCode 官方英文题目。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\"},{\"id\":\"从直觉到优化\",\"heading\":\"从直觉到优化\",\"text\":\"计数哈希与排序都能找，但分别需线性空间或排序时间。把两种不同值成对删除：严格多数即使每次与非多数配对，也不可能全部消失。Boyer-Moore 用候选与票数压缩这项消去过程。\\n\"},{\"id\":\"不变量与正确性\",\"heading\":\"不变量与正确性\",\"text\":\"已处理前缀可分成若干不同值的消去对与 votes 个 candidate 剩余项。相同值增加剩余票，异值消去一票，票归零后下一值重新选候选。删除异值对保持“原严格多数仍为剩余集合严格多数”，因此完整扫描的候选必是多数。\\n\"},{\"id\":\"算法步骤\",\"heading\":\"算法步骤\",\"text\":\"1. votes初始化0，candidate任意初值。\\n2. 票为0时先用当前值建立新候选。\\n3. 相同则加1，不同则减1。\\n4. 在多数存在前提下，返回最后候选。\\n\"},{\"id\":\"手工追踪\",\"heading\":\"手工追踪\",\"text\":\"[5,1,5,2,5,5]：候选5票1；遇1票归0；再选5票1；遇2归0；最后两个5给票2。消去了(5,1)与(5,2)，剩下5、5，所以候选5。最后票数2不是值5在完整数组中的次数4。\\n\"},{\"id\":\"完整-c17-实现\",\"heading\":\"完整 C++17 实现\",\"text\":\"以下内容来自本课 可编译头文件，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0169 {\\nclass Solution {\\npublic:\\n    int majorityElement(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"majority requires data\\\");\\n        int candidate = 0, votes = 0;\\n        for (int value : nums) {\\n            if (votes == 0) candidate = value;\\n            votes += value == candidate ? 1 : -1;\\n        }\\n        return candidate;\\n    }\\n};\\n} // namespace hot100::p0169\\n\"},{\"id\":\"复杂度核算\",\"heading\":\"复杂度核算\",\"text\":\"时间 O(n)，额外空间 O(1)，不修改数组；返回标量。若需验证多数存在，再扫描一次仍为 O(n) 时间。\\n\"},{\"id\":\"c-常见陷阱\",\"heading\":\"C++ 常见陷阱\",\"text\":\"- votes 是净剩余票数，不是候选总频次。\\n- 必须在 votes==0 时重选候选，别把 candidate初值0误当真实先验。\\n- 无多数时算法仍返回某个候选，不能据此宣称它超过一半。\\n\"},{\"id\":\"测试与运行\",\"heading\":\"测试与运行\",\"text\":\"完整测试源文件：2500组固定种子输入保证严格多数，打乱后验证候选并重新计数核实前提；含单项INT_MIN及多轮消票。\\n从仓库根目录运行：\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169\\n/tmp/hot100-cpp/test_p0169\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0169_san\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\"},{\"id\":\"面试追问\",\"heading\":\"面试追问\",\"text\":\"- 无多数保证时如何返回 optional\u003cint>？\\n- 寻找出现次数超过 n/3 的元素，需要几个候选槽？\\n\"},{\"id\":\"练习与提示\",\"heading\":\"练习与提示\",\"text\":\"- 练习1：加入第二遍频次验证。提示：严格比较 count>n/2，注意偶数与奇数。\\n- 练习2：实现两个候选的 n/3 版本。提示：第三种值到来且两槽都非空时同时消票，最终仍需验证。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"169-多数元素c17-推导与实现\\\" tabindex=\\\"-1\\\">169. 多数元素：C++17 推导与实现\u003c/h1>\\n\u003cblockquote>\\n\u003cp>分类：技巧 · 难度：EASY · 官方 Hot 100 顺序：97/100\u003c/p>\\n\u003c/blockquote>\\n\u003ch2 id=\\\"题意与调用约定\\\" tabindex=\\\"-1\\\">题意与调用约定\u003c/h2>\\n\u003cp>非空数组保证存在出现次数严格超过一半的值，返回它。不是“出现次数最多”而是“超过 n/2”；若去掉存在保证，必须增加验证。\u003c/p>\\n\u003cp>题面与最新约束见 \u003ca href=\\\"https://leetcode.cn/problems/majority-element/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">力扣中文官方题目\u003c/a> / \u003ca href=\\\"https://leetcode.com/problems/majority-element/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">LeetCode 官方英文题目\u003c/a>。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\u003c/p>\\n\u003ch2 id=\\\"从直觉到优化\\\" tabindex=\\\"-1\\\">从直觉到优化\u003c/h2>\\n\u003cp>计数哈希与排序都能找，但分别需线性空间或排序时间。把两种不同值成对删除：严格多数即使每次与非多数配对，也不可能全部消失。Boyer-Moore 用候选与票数压缩这项消去过程。\u003c/p>\\n\u003ch2 id=\\\"不变量与正确性\\\" tabindex=\\\"-1\\\">不变量与正确性\u003c/h2>\\n\u003cp>已处理前缀可分成若干不同值的消去对与 votes 个 candidate 剩余项。相同值增加剩余票，异值消去一票，票归零后下一值重新选候选。删除异值对保持“原严格多数仍为剩余集合严格多数”，因此完整扫描的候选必是多数。\u003c/p>\\n\u003ch2 id=\\\"算法步骤\\\" tabindex=\\\"-1\\\">算法步骤\u003c/h2>\\n\u003col>\\n\u003cli>votes初始化0，candidate任意初值。\u003c/li>\\n\u003cli>票为0时先用当前值建立新候选。\u003c/li>\\n\u003cli>相同则加1，不同则减1。\u003c/li>\\n\u003cli>在多数存在前提下，返回最后候选。\u003c/li>\\n\u003c/ol>\\n\u003ch2 id=\\\"手工追踪\\\" tabindex=\\\"-1\\\">手工追踪\u003c/h2>\\n\u003cp>[5,1,5,2,5,5]：候选5票1；遇1票归0；再选5票1；遇2归0；最后两个5给票2。消去了(5,1)与(5,2)，剩下5、5，所以候选5。最后票数2不是值5在完整数组中的次数4。\u003c/p>\\n\u003ch2 id=\\\"完整-c17-实现\\\" tabindex=\\\"-1\\\">完整 C++17 实现\u003c/h2>\\n\u003cp>以下内容来自本课 \u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0169_majority_element.hpp\\\">可编译头文件\u003c/a>，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0169 {\\nclass Solution {\\npublic:\\n    int majorityElement(std::vector&lt;int&gt;&amp; nums) {\\n        if (nums.empty()) throw std::invalid_argument(&quot;majority requires data&quot;);\\n        int candidate = 0, votes = 0;\\n        for (int value : nums) {\\n            if (votes == 0) candidate = value;\\n            votes += value == candidate ? 1 : -1;\\n        }\\n        return candidate;\\n    }\\n};\\n} // namespace hot100::p0169\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"复杂度核算\\\" tabindex=\\\"-1\\\">复杂度核算\u003c/h2>\\n\u003cp>时间 O(n)，额外空间 O(1)，不修改数组；返回标量。若需验证多数存在，再扫描一次仍为 O(n) 时间。\u003c/p>\\n\u003ch2 id=\\\"c-常见陷阱\\\" tabindex=\\\"-1\\\">C++ 常见陷阱\u003c/h2>\\n\u003cul>\\n\u003cli>votes 是净剩余票数，不是候选总频次。\u003c/li>\\n\u003cli>必须在 votes==0 时重选候选，别把 candidate初值0误当真实先验。\u003c/li>\\n\u003cli>无多数时算法仍返回某个候选，不能据此宣称它超过一半。\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"测试与运行\\\" tabindex=\\\"-1\\\">测试与运行\u003c/h2>\\n\u003cp>\u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0169.cpp\\\">完整测试源文件\u003c/a>：2500组固定种子输入保证严格多数，打乱后验证候选并重新计数核实前提；含单项INT_MIN及多轮消票。\u003c/p>\\n\u003cp>从仓库根目录运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>bash\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 bash 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>mkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169\\n/tmp/hot100-cpp/test_p0169\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0169_san\u003c/code>\u003c/pre>\u003c/div>\u003cp>本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\u003c/p>\\n\u003ch2 id=\\\"面试追问\\\" tabindex=\\\"-1\\\">面试追问\u003c/h2>\\n\u003cul>\\n\u003cli>无多数保证时如何返回 optional&lt;int&gt;？\u003c/li>\\n\u003cli>寻找出现次数超过 n/3 的元素，需要几个候选槽？\u003c/li>\\n\u003c/ul>\\n\u003ch2 id=\\\"练习与提示\\\" tabindex=\\\"-1\\\">练习与提示\u003c/h2>\\n\u003cul>\\n\u003cli>练习1：加入第二遍频次验证。提示：严格比较 count&gt;n/2，注意偶数与奇数。\u003c/li>\\n\u003cli>练习2：实现两个候选的 n/3 版本。提示：第三种值到来且两槽都非空时同时消票，最终仍需验证。\u003c/li>\\n\u003c/ul>\\n\",\"source\":\"# 169. 多数元素：C++17 推导与实现\\n\\n> 分类：技巧 · 难度：EASY · 官方 Hot 100 顺序：97/100\\n\\n## 题意与调用约定\\n\\n非空数组保证存在出现次数严格超过一半的值，返回它。不是“出现次数最多”而是“超过 n/2”；若去掉存在保证，必须增加验证。\\n\\n题面与最新约束见 [力扣中文官方题目](https://leetcode.cn/problems/majority-element/) / [LeetCode 官方英文题目](https://leetcode.com/problems/majority-element/)。下文给出独立编写的推导、示例与实现；测试是本地验证，没有声称在线评测已通过。\\n\\n## 从直觉到优化\\n\\n计数哈希与排序都能找，但分别需线性空间或排序时间。把两种不同值成对删除：严格多数即使每次与非多数配对，也不可能全部消失。Boyer-Moore 用候选与票数压缩这项消去过程。\\n\\n## 不变量与正确性\\n\\n已处理前缀可分成若干不同值的消去对与 votes 个 candidate 剩余项。相同值增加剩余票，异值消去一票，票归零后下一值重新选候选。删除异值对保持“原严格多数仍为剩余集合严格多数”，因此完整扫描的候选必是多数。\\n\\n## 算法步骤\\n\\n1. votes初始化0，candidate任意初值。\\n2. 票为0时先用当前值建立新候选。\\n3. 相同则加1，不同则减1。\\n4. 在多数存在前提下，返回最后候选。\\n\\n## 手工追踪\\n\\n[5,1,5,2,5,5]：候选5票1；遇1票归0；再选5票1；遇2归0；最后两个5给票2。消去了(5,1)与(5,2)，剩下5、5，所以候选5。最后票数2不是值5在完整数组中的次数4。\\n\\n## 完整 C++17 实现\\n\\n以下内容来自本课 [可编译头文件](../../../algorithms/cpp/solutions/p0169_majority_element.hpp)，namespace用于让100题可同时进入同一工程。在线提交时一般只保留评测要求的类声明，并按平台要求处理标准库命名；本地辅助头文件负责统一导入标准库。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0169 {\\nclass Solution {\\npublic:\\n    int majorityElement(std::vector\u003cint>& nums) {\\n        if (nums.empty()) throw std::invalid_argument(\\\"majority requires data\\\");\\n        int candidate = 0, votes = 0;\\n        for (int value : nums) {\\n            if (votes == 0) candidate = value;\\n            votes += value == candidate ? 1 : -1;\\n        }\\n        return candidate;\\n    }\\n};\\n} // namespace hot100::p0169\\n```\\n\\n## 复杂度核算\\n\\n时间 O(n)，额外空间 O(1)，不修改数组；返回标量。若需验证多数存在，再扫描一次仍为 O(n) 时间。\\n\\n## C++ 常见陷阱\\n\\n- votes 是净剩余票数，不是候选总频次。\\n- 必须在 votes==0 时重选候选，别把 candidate初值0误当真实先验。\\n- 无多数时算法仍返回某个候选，不能据此宣称它超过一半。\\n\\n## 测试与运行\\n\\n[完整测试源文件](../../../algorithms/cpp/tests/test_p0169.cpp)：2500组固定种子输入保证严格多数，打乱后验证候选并重新计数核实前提；含单项INT_MIN及多轮消票。\\n\\n从仓库根目录运行：\\n\\n```bash\\nmkdir -p /tmp/hot100-cpp\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169\\n/tmp/hot100-cpp/test_p0169\\n# 环境支持时增加运行期检查：\\ng++ -std=c++17 -Wall -Wextra -pedantic -fsanitize=address,undefined -fno-omit-frame-pointer algorithms/cpp/tests/test_p0169.cpp -o /tmp/hot100-cpp/test_p0169_san\\nASAN_OPTIONS=detect_leaks=0 /tmp/hot100-cpp/test_p0169_san\\n```\\n\\n本次环境的LeakSanitizer受ptrace限制，因此命令显式关闭泄漏检测；AddressSanitizer与UndefinedBehaviorSanitizer仍启用。支持泄漏检测的本地环境可移除该环境变量。断言通过说明覆盖输入上的本地结果正确，不能替代证明、完整平台约束核对或在线评测。\\n\\n## 面试追问\\n\\n- 无多数保证时如何返回 optional\u003cint>？\\n- 寻找出现次数超过 n/3 的元素，需要几个候选槽？\\n\\n## 练习与提示\\n\\n- 练习1：加入第二遍频次验证。提示：严格比较 count>n/2，注意偶数与奇数。\\n- 练习2：实现两个候选的 n/3 版本。提示：第三种值到来且两槽都非空时同时消票，最终仍需验证。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0189-rotate-array.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0189-rotate-array.md\",\"title\":\"189. 轮转数组（C++17）\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"普通数组\",\"difficulty\":\"MEDIUM\",\"problemId\":189,\"supplemental\":false,\"questionIds\":[\"LC189\"],\"priorities\":[],\"readingOrder\":null,\"optionalHistorical\":false,\"kind\":\"problem\",\"summary\":\"> 普通数组 · MEDIUM。前置：能读懂本题使用的容器与递归/循环状态。建议先手推，再自己写，最后看实现。\",\"minutes\":4,\"headings\":[{\"id\":\"189-轮转数组c17\",\"text\":\"189. 轮转数组（C++17）\",\"level\":1},{\"id\":\"题意与接口边界\",\"text\":\"题意与接口边界\",\"level\":2},{\"id\":\"从朴素思路走向主解\",\"text\":\"从朴素思路走向主解\",\"level\":2},{\"id\":\"状态与执行步骤\",\"text\":\"状态与执行步骤\",\"level\":2},{\"id\":\"手推一组自建例子\",\"text\":\"手推一组自建例子\",\"level\":2},{\"id\":\"为什么正确\",\"text\":\"为什么正确\",\"level\":2},{\"id\":\"完整-c17-实现\",\"text\":\"完整 C++17 实现\",\"level\":2},{\"id\":\"复杂度与存储边界\",\"text\":\"复杂度与存储边界\",\"level\":2},{\"id\":\"c与边界陷阱\",\"text\":\"C++与边界陷阱\",\"level\":2},{\"id\":\"面试追问先说变化再改算法\",\"text\":\"面试追问：先说变化，再改算法\",\"level\":2},{\"id\":\"自测与迁移练习\",\"text\":\"自测与迁移练习\",\"level\":2}],\"sections\":[{\"id\":\"189-轮转数组c17\",\"heading\":\"189. 轮转数组（C++17）\",\"text\":\"> 普通数组 · MEDIUM。前置：能读懂本题使用的容器与递归/循环状态。建议先手推，再自己写，最后看实现。\\n\"},{\"id\":\"题意与接口边界\",\"heading\":\"题意与接口边界\",\"text\":\"原地将数组向右轮转k步，k为非负；长度n时只需轮转k mod n步。\\n题目与完整输入约束：官方题页。本页为原创教学表达，不重复完整官方题面。\\n\"},{\"id\":\"从朴素思路走向主解\",\"heading\":\"从朴素思路走向主解\",\"text\":\"额外数组可把原下标i送到(i+k)%n，但要O(n)空间。把原数组写成A+B，其中B是末尾k项，目标是B+A。整体反转得reverse(B)+reverse(A)，分别反转两段即可恢复它们内部顺序。\\n\"},{\"id\":\"状态与执行步骤\",\"heading\":\"状态与执行步骤\",\"text\":\"空数组先返回以防模0；k取模；反转整个数组；反转前shift项；反转其余项。三次反转都使用半开迭代器区间，空段反转也合法。\\n\"},{\"id\":\"手推一组自建例子\",\"heading\":\"手推一组自建例子\",\"text\":\"[1,2,3,4,5]、k=7等价于2。全反转[5,4,3,2,1]；前两项反转[4,5,3,2,1]；后三项反转[4,5,1,2,3]，正是末两项移到前面。\\n读到这里先暂停：不看代码，画出每次选择/指针移动后的状态；必须能解释为什么这一步安全，才算理解。\\n\"},{\"id\":\"为什么正确\",\"heading\":\"为什么正确\",\"text\":\"反转操作对拼接满足reverse(A+B)=reverse(B)+reverse(A)。第二、三次反转分别恢复B、A的内部顺序，只改变两段的相对顺序，因此每个元素最终位于正确位置。\\n\"},{\"id\":\"完整-c17-实现\",\"heading\":\"完整 C++17 实现\",\"text\":\"源码：可编译头文件。本地包装的namespace用于把100题同时编译；在线平台提交时只保留类及所需标准头，链表/树节点以平台提供定义为准。\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0189 {\\nclass Solution {\\npublic:\\n    void rotate(std::vector\u003cint>& nums, int k) {\\n        if (nums.empty()) return;\\n        std::size_t shift = static_cast\u003cstd::size_t>(k) % nums.size();\\n        std::reverse(nums.begin(), nums.end());\\n        std::reverse(nums.begin(), nums.begin() + static_cast\u003cstd::ptrdiff_t>(shift));\\n        std::reverse(nums.begin() + static_cast\u003cstd::ptrdiff_t>(shift), nums.end());\\n    }\\n};\\n} // namespace hot100::p0189\\n\"},{\"id\":\"复杂度与存储边界\",\"heading\":\"复杂度与存储边界\",\"text\":\"时间 O(n)，额外空间 O(1)。三段反转的交换总量是线性，和k大小无关；模运算把巨大的k压到合法长度。\\n\"},{\"id\":\"c与边界陷阱\",\"heading\":\"C++与边界陷阱\",\"text\":\"必须先判空再做k%n。官方k非负，本实现没有定义负k左转语义；把负int转size_t再取模不会等价于数学的负轮转。iterator加法用ptrdiff_t兼容差值类型。\\n\"},{\"id\":\"面试追问先说变化再改算法\",\"heading\":\"面试追问：先说变化，再改算法\",\"text\":\"环形替换法也O(1)空间，但索引循环的数量由gcd(n,k)决定，容易漏处理某个环。若传感器缓冲只需逻辑视图，维护头索引可避免实际搬移数组。\\n\"},{\"id\":\"自测与迁移练习\",\"heading\":\"自测与迁移练习\",\"text\":\"练习1：支持有符号k，提示先算((k%n)+n)%n并用足够宽类型。练习2：实现逻辑环形视图，提示所有读取映射到原数组，不应在每次读取时真实rotate。\\n本题可运行测试包含普通、边界或重复调用用例；有适合独立oracle的题还做固定种子的随机/穷举对拍。测试不是在线判题AC记录。仓库根目录可单独运行：\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0189.cpp -o /tmp/hot100-p0189\\n/tmp/hot100-p0189\\n复习门槛：能用自己的话复述状态含义，手推一组未见输入，指出复杂度包含哪些存储，再闭卷实现并通过测试。只记模板而说不出不变式，还需要回到手推。\\n\\n\"}],\"html\":\"\u003ch1 id=\\\"189-轮转数组c17\\\" tabindex=\\\"-1\\\">189. 轮转数组（C++17）\u003c/h1>\\n\u003cblockquote>\\n\u003cp>普通数组 · MEDIUM。前置：能读懂本题使用的容器与递归/循环状态。建议先手推，再自己写，最后看实现。\u003c/p>\\n\u003c/blockquote>\\n\u003ch2 id=\\\"题意与接口边界\\\" tabindex=\\\"-1\\\">题意与接口边界\u003c/h2>\\n\u003cp>原地将数组向右轮转k步，k为非负；长度n时只需轮转k mod n步。\u003c/p>\\n\u003cp>题目与完整输入约束：\u003ca href=\\\"https://leetcode.cn/problems/rotate-array/\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\">官方题页\u003c/a>。本页为原创教学表达，不重复完整官方题面。\u003c/p>\\n\u003ch2 id=\\\"从朴素思路走向主解\\\" tabindex=\\\"-1\\\">从朴素思路走向主解\u003c/h2>\\n\u003cp>额外数组可把原下标i送到(i+k)%n，但要O(n)空间。把原数组写成A+B，其中B是末尾k项，目标是B+A。整体反转得reverse(B)+reverse(A)，分别反转两段即可恢复它们内部顺序。\u003c/p>\\n\u003ch2 id=\\\"状态与执行步骤\\\" tabindex=\\\"-1\\\">状态与执行步骤\u003c/h2>\\n\u003cp>空数组先返回以防模0；k取模；反转整个数组；反转前shift项；反转其余项。三次反转都使用半开迭代器区间，空段反转也合法。\u003c/p>\\n\u003ch2 id=\\\"手推一组自建例子\\\" tabindex=\\\"-1\\\">手推一组自建例子\u003c/h2>\\n\u003cp>[1,2,3,4,5]、k=7等价于2。全反转[5,4,3,2,1]；前两项反转[4,5,3,2,1]；后三项反转[4,5,1,2,3]，正是末两项移到前面。\u003c/p>\\n\u003cp>读到这里先暂停：不看代码，画出每次选择/指针移动后的状态；必须能解释为什么这一步安全，才算理解。\u003c/p>\\n\u003cdetails class=\\\"answer-section\\\" id=\\\"为什么正确\\\" open>\u003csummary>为什么正确\u003cspan class=\\\"summary-hint\\\">展开 / 收起\u003c/span>\u003c/summary>\u003cdiv class=\\\"answer-content\\\">\u003cp>反转操作对拼接满足reverse(A+B)=reverse(B)+reverse(A)。第二、三次反转分别恢复B、A的内部顺序，只改变两段的相对顺序，因此每个元素最终位于正确位置。\u003c/p>\\n\u003c/div>\u003c/details>\u003ch2 id=\\\"完整-c17-实现\\\" tabindex=\\\"-1\\\">完整 C++17 实现\u003c/h2>\\n\u003cp>源码：\u003ca href=\\\"assets/repo/algorithms/cpp/solutions/p0189_rotate_array.hpp\\\">可编译头文件\u003c/a>。本地包装的namespace用于把100题同时编译；在线平台提交时只保留类及所需标准头，链表/树节点以平台提供定义为准。\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>cpp\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 cpp 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>#pragma once\\n#include &quot;../support.hpp&quot;\\n\\nnamespace hot100::p0189 {\\nclass Solution {\\npublic:\\n    void rotate(std::vector&lt;int&gt;&amp; nums, int k) {\\n        if (nums.empty()) return;\\n        std::size_t shift = static_cast&lt;std::size_t&gt;(k) % nums.size();\\n        std::reverse(nums.begin(), nums.end());\\n        std::reverse(nums.begin(), nums.begin() + static_cast&lt;std::ptrdiff_t&gt;(shift));\\n        std::reverse(nums.begin() + static_cast&lt;std::ptrdiff_t&gt;(shift), nums.end());\\n    }\\n};\\n} // namespace hot100::p0189\u003c/code>\u003c/pre>\u003c/div>\u003ch2 id=\\\"复杂度与存储边界\\\" tabindex=\\\"-1\\\">复杂度与存储边界\u003c/h2>\\n\u003cp>时间 O(n)，额外空间 O(1)。三段反转的交换总量是线性，和k大小无关；模运算把巨大的k压到合法长度。\u003c/p>\\n\u003ch2 id=\\\"c与边界陷阱\\\" tabindex=\\\"-1\\\">C++与边界陷阱\u003c/h2>\\n\u003cp>必须先判空再做k%n。官方k非负，本实现没有定义负k左转语义；把负int转size_t再取模不会等价于数学的负轮转。iterator加法用ptrdiff_t兼容差值类型。\u003c/p>\\n\u003ch2 id=\\\"面试追问先说变化再改算法\\\" tabindex=\\\"-1\\\">面试追问：先说变化，再改算法\u003c/h2>\\n\u003cp>环形替换法也O(1)空间，但索引循环的数量由gcd(n,k)决定，容易漏处理某个环。若传感器缓冲只需逻辑视图，维护头索引可避免实际搬移数组。\u003c/p>\\n\u003ch2 id=\\\"自测与迁移练习\\\" tabindex=\\\"-1\\\">自测与迁移练习\u003c/h2>\\n\u003cp>练习1：支持有符号k，提示先算((k%n)+n)%n并用足够宽类型。练习2：实现逻辑环形视图，提示所有读取映射到原数组，不应在每次读取时真实rotate。\u003c/p>\\n\u003cp>本题\u003ca href=\\\"assets/repo/algorithms/cpp/tests/test_p0189.cpp\\\">可运行测试\u003c/a>包含普通、边界或重复调用用例；有适合独立oracle的题还做固定种子的随机/穷举对拍。测试不是在线判题AC记录。仓库根目录可单独运行：\u003c/p>\\n\u003cdiv class=\\\"code-block\\\">\u003cdiv class=\\\"code-toolbar\\\">\u003cspan>sh\u003c/span>\u003cbutton type=\\\"button\\\" class=\\\"copy-code\\\" aria-label=\\\"复制 sh 代码\\\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\\\"0\\\" aria-label=\\\"代码，可横向滚动\\\">\u003ccode>g++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0189.cpp -o /tmp/hot100-p0189\\n/tmp/hot100-p0189\u003c/code>\u003c/pre>\u003c/div>\u003cp>复习门槛：能用自己的话复述状态含义，手推一组未见输入，指出复杂度包含哪些存储，再闭卷实现并通过测试。只记模板而说不出不变式，还需要回到手推。\u003c/p>\\n\",\"source\":\"# 189. 轮转数组（C++17）\\n\\n> 普通数组 · MEDIUM。前置：能读懂本题使用的容器与递归/循环状态。建议先手推，再自己写，最后看实现。\\n\\n## 题意与接口边界\\n\\n原地将数组向右轮转k步，k为非负；长度n时只需轮转k mod n步。\\n\\n题目与完整输入约束：[官方题页](https://leetcode.cn/problems/rotate-array/)。本页为原创教学表达，不重复完整官方题面。\\n\\n## 从朴素思路走向主解\\n\\n额外数组可把原下标i送到(i+k)%n，但要O(n)空间。把原数组写成A+B，其中B是末尾k项，目标是B+A。整体反转得reverse(B)+reverse(A)，分别反转两段即可恢复它们内部顺序。\\n\\n## 状态与执行步骤\\n\\n空数组先返回以防模0；k取模；反转整个数组；反转前shift项；反转其余项。三次反转都使用半开迭代器区间，空段反转也合法。\\n\\n## 手推一组自建例子\\n\\n[1,2,3,4,5]、k=7等价于2。全反转[5,4,3,2,1]；前两项反转[4,5,3,2,1]；后三项反转[4,5,1,2,3]，正是末两项移到前面。\\n\\n读到这里先暂停：不看代码，画出每次选择/指针移动后的状态；必须能解释为什么这一步安全，才算理解。\\n\\n## 为什么正确\\n\\n反转操作对拼接满足reverse(A+B)=reverse(B)+reverse(A)。第二、三次反转分别恢复B、A的内部顺序，只改变两段的相对顺序，因此每个元素最终位于正确位置。\\n\\n## 完整 C++17 实现\\n\\n源码：[可编译头文件](../../../algorithms/cpp/solutions/p0189_rotate_array.hpp)。本地包装的namespace用于把100题同时编译；在线平台提交时只保留类及所需标准头，链表/树节点以平台提供定义为准。\\n\\n```cpp\\n#pragma once\\n#include \\\"../support.hpp\\\"\\n\\nnamespace hot100::p0189 {\\nclass Solution {\\npublic:\\n    void rotate(std::vector\u003cint>& nums, int k) {\\n        if (nums.empty()) return;\\n        std::size_t shift = static_cast\u003cstd::size_t>(k) % nums.size();\\n        std::reverse(nums.begin(), nums.end());\\n        std::reverse(nums.begin(), nums.begin() + static_cast\u003cstd::ptrdiff_t>(shift));\\n        std::reverse(nums.begin() + static_cast\u003cstd::ptrdiff_t>(shift), nums.end());\\n    }\\n};\\n} // namespace hot100::p0189\\n```\\n\\n## 复杂度与存储边界\\n\\n时间 O(n)，额外空间 O(1)。三段反转的交换总量是线性，和k大小无关；模运算把巨大的k压到合法长度。\\n\\n## C++与边界陷阱\\n\\n必须先判空再做k%n。官方k非负，本实现没有定义负k左转语义；把负int转size_t再取模不会等价于数学的负轮转。iterator加法用ptrdiff_t兼容差值类型。\\n\\n## 面试追问：先说变化，再改算法\\n\\n环形替换法也O(1)空间，但索引循环的数量由gcd(n,k)决定，容易漏处理某个环。若传感器缓冲只需逻辑视图，维护头索引可避免实际搬移数组。\\n\\n## 自测与迁移练习\\n\\n练习1：支持有符号k，提示先算((k%n)+n)%n并用足够宽类型。练习2：实现逻辑环形视图，提示所有读取映射到原数组，不应在每次读取时真实rotate。\\n\\n本题[可运行测试](../../../algorithms/cpp/tests/test_p0189.cpp)包含普通、边界或重复调用用例；有适合独立oracle的题还做固定种子的随机/穷举对拍。测试不是在线判题AC记录。仓库根目录可单独运行：\\n\\n```sh\\ng++ -std=c++17 -Wall -Wextra -pedantic algorithms/cpp/tests/test_p0189.cpp -o /tmp/hot100-p0189\\n/tmp/hot100-p0189\\n```\\n\\n复习门槛：能用自己的话复述状态含义，手推一组未见输入，指出复杂度包含哪些存储，再闭卷实现并通过测试。只记模板而说不出不变式，还需要回到手推。\\n\"},{\"path\":\"docs/80-hot100-cpp/problems/0198-house-robber.md\",\"sourceUrl\":\"https://github.com/minimoster/embedded-development-handbook/blob/main/docs/80-hot100-cpp/problems/0198-house-robber.md\",\"title\":\"198. 打家劫舍：C++17 推导与实现\",\"module\":\"hot100cpp\",\"moduleName\":\"Hot100 · C++\",\"category\":\"动态规划\",\"difficulty\":";
